const e=[{id:1,code:"MIL-101",icon:"Siren",accent:"#dc2626",title:"وەڵامدانەوەی خێرا",subtitle:"Rapid Emergency Response",summary:"ڕێکارەکانی وەڵامدانەوەی خێرا لە کاتی ڕووداوە نائاساییەکاندا",blocks:[{body:"لە بارودۆخی سەربازیدا، خێرایی وەڵامدانەوە ژیان دەپارێزێت. ئامادەباشی و ڕاهێنانی بەردەوام پێویستن."},{heading:"١. هەڵسەنگاندنی بارودۆخ (SALUTE)",body:"ڕاپۆرتی خێرا:",points:["S - Size: ژمارە و قەبارە.","A - Activity: چی دەکەن.","L - Location: شوێن (کۆئۆردینات).","U - Unit: یەکە یان جۆر.","T - Time: کات.","E - Equipment: کەرەستە و ئامێر."]},{heading:"٢. وەڵامدانەوەی ئاگر",body:"لە بنکەی سەربازیدا:",points:["ئاگادارکردنەوە: سایرێن یان هاوار، و یەکسەر پەیوەندی بە ١١٥ەوە بکە.","تیمی کوژاندنەوەی ئاگر: بە خێرایی، تەنها بۆ ئاگری بچووک و دوور لە تەقەمەنی.","چوونەدەرەوە: بە ڕێکوپێکی.","کۆبوونەوە: لە خاڵی کۆبوونەوەی دیاریکراو، لەو لایەی با لێیەوە دێت و لە دەرەوەی ناوچەی مەترسی.","سەرژمێری: هەموو کەسێک بژمێردرێت."]},{heading:"٣. فریاکەوتنی مەیدانی",body:"فریاکەوتنی سەرەتایی لە مەیداندا:",points:["خوێنبەربوونی مەترسیدار لە دەست یان قاچ: یەکسەر تۆرنیکێت ببەستە، و کاتی بەستنەکەی بنووسە.","شکان: ئەندامەکە جێگیر بکە و مەیجووڵێنە.","سووتان: ٢٠ خولەک بە ئاوی ڕەوانی فێنک سارد بکەرەوە.","پەستانی سنگ (CPR): ٣٠:٢ (ئەگەر ڕاهێنانت نەبینیوە، تەنها پەستانی سنگ)، و پەیوەندی بە ١٢٢ەوە بکە."]}],media:[{kind:"video",src:"media/videos/mil_response.mp4",title:"وەڵامدانەوەی خێرا",description:"ڕێکارە سەرەکییەکان"}],quiz:[{question:"لە SALUTE دا، پیتی L واتای چییە؟",options:[{text:"ڕووناکی",correct:!1},{text:"شوێن",correct:!0},{text:"درێژی",correct:!1},{text:"لیست",correct:!1}],explanation:"L = Location: شوێن و کۆئۆردینات."},{question:"لە بنکەی سەربازیدا، تیمی کوژاندنەوەی ئاگر دەتوانێت کام ئاگرانە بکوژێنێتەوە؟",options:[{text:"هەر ئاگرێک، بە مەرجێک تیمەکە بە خێرایی بگات",correct:!1},{text:"ئاگری تەنیشت تەقەمەنی، بۆ ئەوەی تەقەمەنییەکە بپارێزرێت",correct:!1},{text:"هەر ئاگرێک، بە مەرجێک ئاگرکوژێنەرەوەی بەس هەبێت",correct:!1},{text:"تەنها ئاگری بچووک کە دوورە لە تەقەمەنی",correct:!0}],explanation:"ئەم وانەیە تیمی کوژاندنەوەی ئاگر تەنها بۆ ئاگری بچووک و دوور لە تەقەمەنی دیاری دەکات؛ یەکسەر ئاگادار بکەرەوە و پەیوەندی بە ١١٥ەوە بکە."},{question:"سەربازێک خوێنبەربوونی مەترسیداری لە قاچەوە هەیە. ئەم وانەیە دەڵێت چی بکەیت؟",options:[{text:"یەکسەر تۆرنیکێت ببەستە و کاتی بەستنەکەی بنووسە",correct:!0},{text:"قاچەکە بەرز بکەرەوە و چاوەڕێ بکە بزانە خوێنەکە خۆی دەوەستێت",correct:!1},{text:"تۆرنیکێت ببەستە و هەر چەند خولەکێک شلی بکەرەوە بۆ ئەوەی خوێن بڕوات",correct:!1},{text:"برینەکە بە ئاو بشۆ و بەبێ داپۆشین جێی بهێڵە بۆ ئەوەی وشک ببێتەوە",correct:!1}],explanation:"بۆ خوێنبەربوونی مەترسیدار لە دەست یان قاچ، وانەکە دەڵێت: یەکسەر تۆرنیکێت ببەستە و کاتی بەستنەکەی بنووسە."}]},{id:2,code:"MIL-102",icon:"Tent",accent:"#16a34a",title:"دامەزراندنی کەمپ",subtitle:"Safe Camp Setup",summary:"دامەزراندنی کەمپێکی سەربازی بە سەلامەتی",blocks:[{body:"کەمپی سەربازی دەبێت لە مەترسییە سروشتییەکان و ئەو مەترسییانەی دەستکردی مرۆڤن پارێزراو بێت."},{heading:"١. هەڵبژاردنی شوێن",body:"شوێنی گونجاو:",points:["شوێنی بەرز: نەک لە دۆڵ و شیوەکاندا (مەترسیی لافاو).","نزیک لە ئاو، بەڵام نەک زۆر نزیک.","پارێزراو لە با، بەڵام نەک لە ژێر درەختە گەورەکاندا (لق و هەورەتریشقە).","ڕێگای هاتن و چوونەدەرەوە: ئاشکرا و کراوە."]},{heading:"٢. ڕێکخستنی کەمپ",body:"شوێنە سەرەکییەکان:",points:["چادر: ڕیز بە ڕیز، بە مەودایەک لە نێوانیاندا.","شوێنی ئاگر: دوور لە چادرەکان.","دەستاو (تەوالێت): دوور لە ئاو و خواردن، و لەو لایەی با بۆی دەڕوات.","خاڵی فریاکەوتنی سەرەتایی: لە ناوەڕاستی کەمپدا."]},{heading:"٣. سەلامەتیی کەمپ",body:"ڕێسا گرنگەکان:",points:["ئاگر: چاودێریی بەردەوام (٢٤ کاتژمێر).","کارەبا: مۆلیدە (جەنەراتۆر) دوور لە چادرەکان بێت (مەترسیی گازی CO).","سووتەمەنی: لە شوێنێکی تایبەت و دوور.","ئاگرکوژێنەرەوە: نزیک لە چادرەکان و شوێنەکانی ئاگر."]}],media:[{kind:"image",src:"media/images/mil_camp.png",title:"کەمپ",description:"ڕێکخستن"}],quiz:[{question:"شوێنی ئاگر دەبێت لە کوێ بێت؟",options:[{text:"نزیک لە چادرەکان",correct:!1},{text:"دوور لە چادرەکان",correct:!0},{text:"لە ناو چادردا",correct:!1},{text:"هەر شوێنێک بێت",correct:!1}],explanation:"دوور لە چادرەکان، بۆ ئەوەی ئاگر بۆ چادرەکان بڵاو نەبێتەوە."},{question:"بۆچی دەبێت کەمپ لە شوێنی بەرز دابمەزرێت و نەک لە دۆڵ و شیوەکاندا؟",options:[{text:"چونکە شوێنی بەرز باشتر لە با پارێزراوە",correct:!1},{text:"بەهۆی مەترسیی لافاوەوە",correct:!0},{text:"چونکە نزیکترە لە درەختە گەورەکان بۆ سێبەر",correct:!1},{text:"چونکە دۆڵەکان زۆر دوورن لە ئاو",correct:!1}],explanation:"وانەکە شوێنی بەرز هەڵدەبژێرێت نەک دۆڵ و شیوەکان، بەهۆی مەترسیی لافاوەوە."},{question:"مۆلیدە (جەنەراتۆر) لە کەمپدا دەبێت لە کوێ بێت، و بۆچی؟",options:[{text:"لە ناو چادرێکدا، بۆ پاراستنی لە باران و تۆز",correct:!1},{text:"لە تەنیشت شوێنی سووتەمەنی، بۆ ئەوەی پڕکردنەوەی خێرا بێت",correct:!1},{text:"دوور لە چادرەکان، بەهۆی مەترسیی گازی CO",correct:!0},{text:"لە ناوەڕاستی کەمپدا، لە تەنیشت خاڵی فریاکەوتنی سەرەتایی",correct:!1}],explanation:"مۆلیدە دەبێت دوور لە چادرەکان بێت بەهۆی مەترسیی گازی CO؛ سووتەمەنی لە شوێنێکی تایبەت و دوور دادەنرێت."}]},{id:3,code:"MIL-103",icon:"HeartPulse",accent:"#dc2626",title:"فریاکەوتنی مەیدانی (MARCH)",subtitle:"Tactical First Aid",summary:"فریاکەوتنی سەرەتایی لە بارودۆخی مەیدانیدا — ڕیزبەندیی MARCH",blocks:[{body:"فریاکەوتنی مەیدانی جیاوازە لە فریاکەوتنی ئاسایی: خێرایی و ڕیزبەندیی کارەکان گرنگترن. ڕیزبەندیی MARCH کە لە پرۆتۆکۆلی چاودێریی تاکتیکیی بریندارانەوە (TCCC) وەرگیراوە، ژیان دەپارێزێت."},{heading:"١. ڕیزبەندیی MARCH",body:"ڕیزبەندیی کارەکانی فریاکەوتن:",points:["M - Massive Hemorrhage: خوێنبەربوونی مەترسیدار یەکەمە: پەستانی ڕاستەوخۆ، پڕکردنەوەی برین، تۆرنیکێت.","A - Airway: ڕێڕەوی هەناسە بکەرەوە.","R - Respiration: هەناسەدان و برینەکانی سنگ بپشکنە.","C - Circulation: سووڕانی خوێن و نیشانەکانی شۆک.","H - Hypothermia / Head Injury: بریندار گەرم ڕابگرە و برینەکانی سەر بپشکنە."]},{heading:"٢. تۆرنیکێت (Tourniquet)",body:"بۆ خوێنبەربوونی مەترسیدار لە دەست یان قاچ:",points:["شوێن: ٥-٧ سم سەرووتر لە برینەکە، نەک لەسەر جومگە.","توندکردن: دارەکە بسووڕێنە تا خوێنەکە دەوەستێت.","کات: کاتی بەستنەکە لەسەر تۆرنیکێتەکە یان لەسەر نێوچەوانی بریندار بنووسە.","هەرگیز لە مەیداندا شلی مەکەرەوە؛ تەنها تیمی پزیشکی لە نەخۆشخانە دەتوانێت لای ببات.","بریندار بە خێرایی بگوازەرەوە (MEDEVAC) و کاتی بەستنەکە بە تیمی پزیشکی بڵێ."]},{heading:"٣. دۆخی ڕزگاری (Recovery Position)",body:"بۆ کەسێکی بێهۆش کە بە شێوەی ئاسایی هەناسە دەدات، ئەگەر گومانی برینی مل، پشت، سمت یان ئێسکی حەوز نەبوو:",points:["١. بریندارەکە بەسەر لایەکیدا وەرگێڕە.","٢. دەستی سەرەوەی بخە ژێر ڕوومەتی.","٣. ئەژنۆی قاچی سەرەوەی بچەمێنەوە بۆ ئەوەی بەسەر سکدا وەرنەگەڕێت.","٤. سەری کەمێک بەرەو دواوە ببە بۆ ئەوەی ڕێڕەوی هەناسە کراوە بمێنێتەوە.","٥. بە بەردەوامی هەناسەی بپشکنە تا هاوکاری دەگات (١٢٢ یان MEDEVAC)."]},{heading:"٤. سووتان",body:"چارەسەری سووتان لە مەیداندا:",points:["ساردکردنەوە: ٢٠ خولەک بە ئاوی ڕەوانی پاک و فێنک.","داپۆشین: پەڕۆی برینپێچی ستێریل یان نایلۆنی پاک، بێ پێچانەوەی توند.","سەهۆڵ بەکار مەهێنە!","کرێم، ڕۆن و هەویری ددان بەکار مەهێنە؛ بڵقەکان مەتەقێنە.","سووتانی گەورە یان سووتانی ڕوخسار، دەست و جومگەکان: بە خێرایی بگوازەرەوە (١٢٢ یان MEDEVAC)."]}],media:[{kind:"video",src:"media/videos/mil_tourniquet.mp4",title:"تۆرنیکێت",description:"چۆنیەتیی بەکارهێنان"},{kind:"image",src:"media/images/mil_recovery.png",title:"دۆخی ڕزگاری",description:"بۆ بریندارێکی بێهۆش کە هەناسە دەدات"}],quiz:[{question:"لە ڕیزبەندیی MARCH دا، چی یەکەمە؟",options:[{text:"هەناسە",correct:!1},{text:"خوێنبەربوونی مەترسیدار",correct:!0},{text:"دڵ",correct:!1},{text:"سەرما",correct:!1}],explanation:"M یەکەمە، چونکە لە مەیداندا خوێنبەربوون گەورەترین هۆکاری ئەو مردنانەیە کە دەتوانرێت ڕێگرییان لێ بکرێت."},{question:"تۆرنیکێت کەی بەکار دەهێنرێت؟",options:[{text:"بۆ هەموو برینەکان",correct:!1},{text:"خوێنبەربوونی مەترسیدار لە دەست یان قاچ",correct:!0},{text:"برینەکانی سەر",correct:!1},{text:"برینەکانی سک",correct:!1}],explanation:"تەنها بۆ خوێنبەربوونی مەترسیدار لە دەست و قاچەکان؛ کاتی بەستنەکە بنووسە و هەرگیز لە مەیداندا شلی مەکەرەوە."},{question:"تۆرنیکێت لە کوێ دەبەسترێت؟",options:[{text:"ڕاستەوخۆ لەسەر برینەکە، بۆ ئەوەی پەستان بخاتە سەر دەمارە خوێنبەرەکە",correct:!1},{text:"لەسەر نزیکترین جومگە، چونکە لەوێ باشتر دەگرێت",correct:!1},{text:"خوارتر لە برینەکە، لە نێوان برینەکە و دەست یان پێدا",correct:!1},{text:"٥-٧ سم سەرووتر لە برینەکە، نەک لەسەر جومگە",correct:!0}],explanation:"وانەکە تۆرنیکێت ٥-٧ سم سەرووتر لە برینەکە دادەنێت، نەک لەسەر جومگە؛ کاتی بەستنەکە لەسەر تۆرنیکێتەکە یان لەسەر نێوچەوانی بریندار بنووسە."}]},{id:4,code:"MIL-104",icon:"Radio",accent:"#2563eb",title:"پەیوەندیی کاتی نائاسایی",subtitle:"Emergency Communications",summary:"سیستەمەکانی پەیوەندیکردن لە کاتی باری نائاساییدا",blocks:[{body:"پەیوەندیی باش کلیلی سەرکەوتنە. لە کارەساتەکاندا، لەوانەیە تۆڕەکانی پەیوەندی لە کار بکەون."},{heading:"١. سیستەمەکانی پەیوەندی",body:"جۆرەکانی پەیوەندیکردن:",points:["ڕادیۆ: ئامرازی سەرەکی، هەمیشە ئامادە.","مۆبایل: ئەگەر تۆڕ هەبێت.","ساتەلایت: بۆ شوێنە دوورەکان.","ڕووناکی: ئاماژەی بینراو.","دەنگ: سایرێن، فیکە، هاوار."]},{heading:"٢. پەیامی دروست",body:"چۆن پەیام بگەیەنیت:",points:["شوێن: کۆئۆردیناتی دروست.","دۆخ: چی ڕوویداوە.","ژمارە: چەند کەس و چەند بریندار.","پێداویستی: چی پێویستە.","دووبارەکردنەوە: بۆ دڵنیابوونەوە."]},{heading:"٣. کۆدەکانی باری نائاسایی",body:"نموونەی کۆدە ڕەنگییەکان (کۆدەکان لە دامەزراوەیەکەوە بۆ دامەزراوەیەکی تر جیاوازن؛ پەیڕەوی ڕێنماییەکانی فەرماندەییەکەت بکە):",points:["کۆدی سوور: ئاگر.","کۆدی شین: باری نائاسایی پزیشکی.","کۆدی ڕەش: هەڕەشەی تەقەمەنی.","کۆدی زەرد: ئاگادارکردنەوە و ئامادەباشی.","کۆدی سەوز: سەلامەتی، دۆخەکە کۆتایی هات."]}],media:[{kind:"video",src:"media/videos/mil_radio.mp4",title:"ڕادیۆ",description:"بەکارهێنان"}],quiz:[{question:"کۆدی سوور واتای چییە؟",options:[{text:"سەلامەتی",correct:!1},{text:"باری نائاسایی پزیشکی",correct:!1},{text:"ئاگر",correct:!0},{text:"ئاگادارکردنەوە",correct:!1}],explanation:"کۆدی سوور = ئاگرکەوتنەوە."},{question:"پەیامی دروستی باری نائاسایی دەبێت چی تێدا بێت؟",options:[{text:"شوێن، دۆخ، ژمارەی کەسەکان و بریندارەکان و پێداویستی",correct:!0},{text:"تەنها ناوی خۆت و یەکەکەت، بۆ ئەوەی بنکە پەیوەندیت پێوە بکات",correct:!1},{text:"دۆخ و داوای یارمەتی؛ شوێن دەتوانێت دواتر بێت",correct:!1},{text:"پلەکەت، کات و کەشوهەوای شوێنەکە",correct:!1}],explanation:"پەیامی دروست کۆئۆردیناتی دروستی شوێن، چی ڕوویداوە، چەند کەس و چەند بریندار، و چی پێویستە دیاری دەکات، و بۆ دڵنیابوونەوە دووبارە دەکرێتەوە."},{question:"بۆچی دەبێت پەیڕەوی ڕێنماییەکانی فەرماندەییەکەت بکەیت بۆ کۆدە ڕەنگییەکانی باری نائاسایی؟",options:[{text:"چونکە ڕەنگەکان بە یاسای نێودەوڵەتی بۆ هەموو هێزەکان دیاری کراون",correct:!1},{text:"چونکە کۆدەکان لە دامەزراوەیەکەوە بۆ دامەزراوەیەکی تر جیاوازن",correct:!0},{text:"چونکە تەنها فەرماندەکان دەتوانن کۆدەکان بە دەنگی بەرز بڵێن",correct:!1},{text:"چونکە کۆدەکان بۆ ئاسایش هەموو ڕۆژێک دەگۆڕدرێن",correct:!1}],explanation:"کۆدەکان لە دامەزراوەیەکەوە بۆ دامەزراوەیەکی تر جیاوازن، بۆیە ڕەنگەکانی ئەم وانەیە تەنها نموونەن؛ پەیڕەوی ڕێنماییەکانی فەرماندەییەکەت بکە."}]},{id:5,code:"MIL-105",icon:"Biohazard",accent:"#ca8a04",title:"پاراستن لە مەترسییەکانی CBRN",subtitle:"Chemical, Biological, Radiological, Nuclear",summary:"پاراستن لە مەترسییە کیمیایی، بایۆلۆجی، تیشکی و ناوکییەکان",blocks:[{body:"مەترسییە کیمیایی، بایۆلۆجی، تیشکی و ناوکییەکان (CBRN) هەڕەشەیەکی ڕاستەقینەن بۆ هێزە سەربازییەکان و هاووڵاتیانی مەدەنی. پێویستە پێشمەرگە ئەم مەترسییانە بناسن و بزانن چۆن خۆیانی لێ بپارێزن."},{heading:"١. مەترسیی کیمیایی (C)",body:"ماددە کیمیاییەکان:",points:["ماددە دەمارییەکان (Nerve Agents، وەک Sarin و VX): کوشندەترینن.","ماددە خنکێنەرەکان (Choking Agents، وەک Chlorine و Phosgene): زیان بە سییەکان دەگەیەنن.","ماددە بڵقدروستکەرەکان (Blister Agents، وەک Mustard): پێست، چاو و سییەکان دەسووتێنن.","گازی فرمێسکڕێژ (CS): لە ڕاهێناندا بۆ تاقیکردنەوەی دەمامک بەکار دەهێنرێت.","نیشانەکان: فرمێسک، ئاوی لووت، تەنگیی سنگ، کۆکە، بۆنێکی نائاسایی.","کار: یەکسەر دەمامک بپۆشە، ئاگادار بکەرەوە، و لە ناوچەکە دەربچە بەرەو سەرەوەی با (ئەو لایەی با لێیەوە دێت) و شوێنە بەرزەکان."]},{heading:"٢. مەترسیی بایۆلۆجی (B)",body:"ماددە بایۆلۆجییەکان:",points:["ئەنسراکس (Anthrax): بەکتریایە، لەوانەیە وەک تۆزێکی سپی بێت.","تاعوون (Plague): بەکتریایە، جۆرە سییەکەی لە ڕێگەی هەواوە لە مرۆڤەوە بۆ مرۆڤ دەگوازرێتەوە.","ئاوڵە (Smallpox): ڤایرۆسە، بە خێرایی بڵاو دەبێتەوە.","نیشانەکان: تا، کۆکە، لاوازی — دوای چەند ڕۆژ یان چەند هەفتەیەک دەردەکەون.","پاراستن: دەمامک، دەستکێش، دووری لە نەخۆشەکان، و چاودێریی تەندروستی.","چارەسەر: ئەنتیبایۆتیک یان ڤاکسین، بەپێی بڕیاری پزیشک."]},{heading:"٣. تیشکی (R) و ناوکی (N)",body:"مەترسیی تیشکە ڕادیۆئەکتیڤەکان:",points:["بۆمبی پیس (Dirty Bomb): تەقەمەنی + ماددەیەکی تیشکدەر.","ناوکی: تەقینەوەی چەکی ناوکی.","پاراستن: کات + دووری + بەربەست (Time, Distance, Shielding).","بەربەست: دیواری ئەستوور، کۆنکرێت، خۆڵ.","پاککردنەوە (Decontamination): جلە دەرەکییەکان دابکەنە و لەش بە ئاو و سابوون بشۆ.","کات: تا کەمتر لە نزیکی بیت، باشترە."]},{heading:"٤. کەرەستەکانی پاراستن (PPE)",body:"ئاستەکانی MOPP (Mission Oriented Protective Posture) — هەر ئاستێک کەرەستەیەک بۆ سەر ئاستی پێش خۆی زیاد دەکات:",points:["دەمامکی گاز بە فلتەری CBRN، و جل، پۆتین و دەستکێشی پاراستن هەمیشە لەبەردەست بن.","MOPP 1: جلی پاراستن (Overgarment) لەبەر دەکرێت.","MOPP 2: MOPP 1 + پۆتینی پاراستن (Overboots).","MOPP 3: MOPP 2 + دەمامکی گاز و کڵاوەکەی (Hood).","MOPP 4: MOPP 3 + دەستکێش — پاراستنی تەواو.","دەرزیی خۆکاری Atropine (Auto-Injector): بۆ ژەهراویبوون بە ماددە دەمارییەکان، بەپێی ڕێنمایی پزیشکی؛ و ڕاهێنانی بەردەوام لەسەر MOPP."]}],media:[{kind:"video",src:"media/videos/mil_cbrn.mp4",title:"CBRN",description:"ناسین و پاراستن"},{kind:"image",src:"media/images/mil_mopp.png",title:"ئاستەکانی MOPP",description:"٤ ئاست"}],quiz:[{question:"CBRN کورتکراوەی چییە؟",options:[{text:"کۆمپیوتەر",correct:!1},{text:"کیمیایی، بایۆلۆجی، تیشکی، ناوکی",correct:!0},{text:"پەیوەندی",correct:!1},{text:"فریاکەوتنی سەرەتایی",correct:!1}],explanation:"کیمیایی (Chemical)، بایۆلۆجی (Biological)، تیشکی (Radiological)، ناوکی (Nuclear)."},{question:"سێ هۆکارەکەی پاراستن لە تیشک کامانەن؟",options:[{text:"ئاو، خواردن، هەوا",correct:!1},{text:"کات، دووری، بەربەست",correct:!0},{text:"ڕاکردن، پەستان، گەرمی",correct:!1},{text:"ڕادیۆ، مۆبایل، ساتەلایت",correct:!1}],explanation:"کاتی کەم، دووریی زۆر و بەربەستی ئەستوور (Time, Distance, Shielding)."},{question:"Atropine بۆ چییە؟",options:[{text:"سووتان",correct:!1},{text:"خوێنبەربوون",correct:!1},{text:"ژەهراویبوون بە ماددە دەمارییەکان",correct:!0},{text:"شکان",correct:!1}],explanation:"Atropine دەرمانێکە دژی ژەهراویبوون بە ماددە دەمارییەکان (Nerve Agents)."}]},{id:6,code:"MIL-106",icon:"Bomb",accent:"#ea580c",title:"مەترسیی مین و IED",subtitle:"Mine Awareness & IED Safety",summary:"ناسینی مەترسیی مین و بۆمبی دەستکرد (IED) و خۆپاراستن",blocks:[{body:"مین و بۆمبە دەستکردەکان مەترسییەکی ئاشکران لە هەرێمی کوردستان. ئەم مەترسییە تەنها هی سەربازان نییە — هاووڵاتیانی مەدەنیش دەبنە قوربانی."},{heading:"١. جۆرەکانی مین",body:"مینە سەرەکییەکان:",points:["مینی دژە پیادە (AP): بە پەستانی پێ دەتەقێتەوە.","مینی دژە ئۆتۆمبێل (AT): پەستانێکی گەورەتری پێویستە.","مینی تەل (Tripwire): تەلێکی باریک کە بە زەحمەت دەبینرێت.","Claymore: لە دوورەوە دەتەقێنرێتەوە.","بۆمبە هێشووییەکان (Cluster): بچووک و ڕەنگاوڕەنگن — منداڵان وەک یاری دەیانبینن!","نیشانەکانی ناوچەی مین: تابلۆی سوور (کاسەی سەر یان «مین»)، بەردی سوورڕەنگکراو، تەلی دەوروبەر — هەرگیز لێیان مەپەڕەرەوە."]},{heading:"٢. IED — بۆمبە دەستکردەکان",body:"جۆرەکان:",points:["RCIED: لە ڕێگەی ڕیمۆت یان مۆبایلەوە دەتەقێنرێتەوە.","VOIED: کاتێک قوربانی دەستی لێ دەدات یان پێی لەسەر دادەنێت.","Timed IED: بە کاتژمێر (تایمەر).","VBIED: ئۆتۆمبێلێکی بۆمبڕێژکراو.","نیشانەکان: وایەری نەناسراو، ئۆتۆمبێلی بەجێهێڵراو، خۆڵی تازە هەڵکەنراو.","ئەگەر بینیت: نزیکی مەبەوە! دوور بکەوەرەوە و ئاگادار بکەرەوە."]},{heading:"٣. پێنج C ی IED (5Cs)",body:"٥ هەنگاو:",points:["١. Confirm: لە دوورەوە دڵنیا ببەوە — نزیکی مەبەوە و دەستی لێ مەدە.","٢. Clear: هەموو کەسێک دوور بخەرەوە، لانیکەم ٣٠٠ مەتر.","٣. Call: ڕاپۆرت بدە بە فەرماندەییەکەت و تیمی EOD، و پەیوەندی بە ١١٥ەوە بکە.","٤. Cordon: ناوچەکە دابخە و ئاگاداری بۆمبی دووەم (Secondary) بە.","٥. Control: کۆنترۆڵی ناوچەکە بکە تا تیمی EOD دەگات.","دووری: لانیکەم ٣٠٠ مەتر بۆ IED؛ بۆ VBIED زیاتر: نزیکەی ٦٠٠ مەتر بۆ ئۆتۆمبێلێکی بچووک و تا ٢٨٠٠ مەتر بۆ بارهەڵگرێکی گەورە."]},{heading:"٤. هۆشیاریی مەدەنی",body:"فێرکردنی خەڵک:",points:["منداڵان: دەست لە شتە نەناسراوەکان مەدەن!","جووتیاران و بیناسازان: پێش هەڵکەندنی زەوی، لە لایەنی پەیوەندیدار بپرسن؛ نەبوونی نیشانەی ئاگادارکردنەوە بەو مانایە نییە کە زەوییەکە سەلامەتە، چونکە زۆربەی ناوچە مەترسیدارەکان نیشانە نەکراون.","شوانەکان: مەڕوماڵات لە ناوچەکانی مین مەلەوەڕێنن.","نیشانەکانی ئاگادارکردنەوەی مین بناسە، ڕێزیان لێ بگرە و هەرگیز لایان مەبە.","ئەگەر مین یان هەر شتێکی نەناسراوت بینی: لێی نزیک مەبەرەوە، خەڵک ئاگادار بکەرەوە و لێی دوور بخەرەوە، شوێنەکەی لە بیر مەکە و بە لایەنی پەیوەندیدار ڕایبگەیەنە؛ لە باری نائاساییدا پەیوەندی بە ١١٥ەوە بکە.","هەرگیز دەستی لێ مەدە و هەڵیمەگرە — مردنە!","ئەگەر زانیت لەوانەیە لە ناوچەیەکی میندا بیت: یەکسەر بوەستە، بێجووڵە بمێنەوە و پێیەکانت مەجووڵێنە، داوای یارمەتی بکە و چاوەڕێ بکە تا تیمێکی ڕاهێنراو دەگات."]}],media:[{kind:"video",src:"media/videos/mil_mine.mp4",title:"مین و IED",description:"ناسین و خۆپاراستن"},{kind:"image",src:"media/images/mil_mine_types.png",title:"جۆرەکانی مین",description:"وێنە"}],quiz:[{question:"ئەگەر IED یەکت بینی، چی دەکەیت؟",options:[{text:"بچۆ نزیکی",correct:!1},{text:"دەستی لێ بدە",correct:!1},{text:"دوور بکەوەرەوە و ئاگادار بکەرەوە",correct:!0},{text:"نزیکی ببەوە و وێنەی بگرە",correct:!1}],explanation:"دوور بکەوەرەوە، خەڵک دوور بخەرەوە و فەرماندەییەکەت و تیمی EOD ئاگادار بکەرەوە."},{question:"دووریی سەلامەت لە ئۆتۆمبێلێکی بۆمبڕێژکراو (VBIED) چەندە؟",options:[{text:"١٠٠ مەتر",correct:!1},{text:"٣٠٠ مەتر",correct:!1},{text:"لانیکەم ٦٠٠ مەتر بۆ ئۆتۆمبێلێکی بچووک، و زیاتر بۆ ئۆتۆمبێلە گەورەترەکان",correct:!0},{text:"٥٠ مەتر ئەگەر لە پشت دیوارێکەوە بیت",correct:!1}],explanation:"بەپێی کارتی دووریی CISA و FBI: ئۆتۆمبێلێکی بچووک نزیکەی ٦٠٠ مەتر، ڤان یان SUV نزیکەی ٧٣٠ مەتر، و بارهەڵگرە گەورەکان ١٢٠٠-٢٨٠٠ مەتر."},{question:"بۆمبە هێشووییەکان (Cluster) بۆچی بۆ منداڵان مەترسیدارن؟",options:[{text:"چونکە گەورەن",correct:!1},{text:"بچووک و ڕەنگاوڕەنگن — وەک یاری دەردەکەون",correct:!0},{text:"چونکە ناتەقنەوە",correct:!1},{text:"چونکە تەنها سەربازان دەکوژن",correct:!1}],explanation:"بچووک و ڕەنگاوڕەنگن، منداڵان وەک یاری هەڵیان دەگرن."}]},{id:7,code:"MIL-107",icon:"Compass",accent:"#0d9488",title:"مانەوە بە زیندوویی و دۆزینەوەی ئاراستە",subtitle:"Survival Skills & Navigation",summary:"هونەرەکانی مانەوە بە زیندوویی لە مەیداندا، دۆزینەوەی ئاراستە و ڕزگاربوون",blocks:[{body:"لە بارودۆخی مەیدانیدا، لەوانەیە پێشمەرگە لە تیمەکەی جیا ببێتەوە. ئاو، ئاگر، پەناگە و ئاراستە چوار کۆڵەکەی مانەوە بە زیندوویین."},{heading:"١. ئاو — یەکەم ئەولەویەت",body:"بە گشتی مرۆڤ نزیکەی ٣ ڕۆژ بێ ئاو دەژیت، و لە گەرمادا کەمتر:",points:["سەرچاوە: ڕووبار، کانی، باران، شەونم.","کوڵاندن: ١ خولەک بە کوڵانی تەواو (لە بەرزیی زیاتر لە ٢٠٠٠ مەتر: ٣ خولەک).","حەبی پاککردنەوە: کلۆر یان یۆد (Chlorine/Iodine)، بەپێی ڕێنماییەکانی سەر پاکەتەکە.","پاڵاوتن: بە پارچە قوماشێکی پاک بیپاڵێوە، پاشان بیکوڵێنە.","ئاوی وەستاو بەبێ پاککردنەوە مەخۆرەوە.","هەمیشە بوتڵێک ئاو لەگەڵ خۆت ببە."]},{heading:"٢. ئاگر",body:"ئاگر = گەرمی + ڕووناکی + ئاماژە:",points:["سێگۆشەی ئاگر: سووتەمەنی + ئۆکسجین + گەرمی.","داری وشک: لە لقە بچووکەکانەوە دەست پێ بکە.","هەڵکردن: چەخماخە، شقارتە، یان بەرد و ئاسن.","مەودا لە نێوان دارەکاندا بهێڵەوە بۆ ئەوەی هەوا بگاتێ.","شوێنێکی پاککراوە لە گژوگیای وشک هەڵبژێرە و دەوروبەری ئاگرەکە بە بەرد بگرە.","سێ ئاگر بە شێوەی سێگۆشە = ئاماژەی داوای فریاکەوتن (SOS)."]},{heading:"٣. پەناگە",body:"پاراستن لە کەشوهەوا:",points:["ئەشکەوت: باشترین پەناگەن، بەڵام ئاگاداری داڕمان و ئاژەڵەکان بە.","لق و پۆپی درەخت.","بەرد و خۆڵ.","دەرگای پەناگەکە ڕووەو با نەبێت.","ئاگر نزیک لە پەناگەکە، بەڵام بە دوورییەکی سەلامەت.","خۆت لە ساردیی زەوی بپارێزە (لق، گیا یان کارتۆن لە ژێر خۆتدا دابنێ)."]},{heading:"٤. دۆزینەوەی ئاراستە",body:"بەبێ GPS:",points:["قیبلەنما (کۆمپاس): ئاراستە و گۆشەی ئاراستە (Azimuth).","خۆر: لە ڕۆژهەڵاتەوە هەڵدێت و لە ڕۆژئاوا ئاوا دەبێت.","ئەستێرەی باکوور (Polaris): ئاراستەی باکوور نیشان دەدات.","قەوزە لەسەر درەختەکان نیشانەیەکی باوەڕپێکراو نییە بۆ دۆزینەوەی باکوور.","ئاو بەرەو خوارەوە دەڕوات؛ بەدوای ڕووبارەکەدا بڕۆ بەرەو گوند و ڕێگاکان.","سێ دەنگ، سێ ئاگر یان سێ ڕووناکی = ئاماژەی داوای فریاکەوتن (SOS)."]}],media:[{kind:"video",src:"media/videos/mil_survival.mp4",title:"مانەوە بە زیندوویی",description:"هونەرە سەرەکییەکان"}],quiz:[{question:"بە گشتی، مرۆڤ دەتوانێت چەند ڕۆژ بێ ئاو بژیت؟",options:[{text:"١",correct:!1},{text:"٣",correct:!0},{text:"٧",correct:!1},{text:"١٤",correct:!1}],explanation:"نزیکەی ٣ ڕۆژ (یاسای سێیەکان)؛ لە گەرمادا ماوەکە زۆر کەمترە."},{question:"سێ ئاگر بە شێوەی سێگۆشە واتای چییە؟",options:[{text:"پاراستن",correct:!1},{text:"SOS — داوای هاوکاری",correct:!0},{text:"ئاگرکەوتنەوە",correct:!1},{text:"هیچ واتایەکی نییە",correct:!1}],explanation:"ئاماژەیەکی جیهانییە بۆ داوای هاوکاری (SOS)."},{question:"ئاو دەبێت چەند بکوڵێنرێت بۆ ئەوەی خواردنەوەی سەلامەت بێت؟",options:[{text:"تەنها تا یەکەم بڵقە بچووکەکان لە بنی مەنجەڵەکەدا دەردەکەون",correct:!1},{text:"١٠ چرکە، پاشان دەبێت داپۆشراو جێبهێڵرێت تا سارد دەبێتەوە",correct:!1},{text:"١ خولەک بە کوڵانی تەواو؛ لە بەرزیی زیاتر لە ٢٠٠٠ مەتر، ٣ خولەک",correct:!0},{text:"لانیکەم ٣٠ خولەک، ئەگەرنا میکرۆبەکان دەمێننەوە",correct:!1}],explanation:"ئاو ١ خولەک بە کوڵانی تەواو بکوڵێنە (لە بەرزیی زیاتر لە ٢٠٠٠ مەتر: ٣ خولەک)؛ ئاوی وەستاو بەبێ پاککردنەوە مەخۆرەوە."}]},{id:8,code:"MIL-108",icon:"Truck",accent:"#4b5563",title:"سەلامەتیی ئۆتۆمبێل و کاروان",subtitle:"Vehicle & Convoy Safety",summary:"سەلامەتیی گواستنەوەی سەربازی و کاروانەکان",blocks:[{body:"ڕووداوەکانی هاتوچۆ، بۆسە و بۆمبە دەستکردەکان (IED) لەسەر ڕێگاکان مەترسییە سەرەکییەکانن."},{heading:"١. ڕێساکانی لێخوڕینی سەربازی",body:"بنەماکان:",points:["کڵاوی پاراستن هەمیشە.","لە ئۆتۆمبێلی کراوەدا سەرنشین زیاد مەکە.","پشتێنی سەلامەتی (قایش) بۆ هەموو سەرنشینان.","ڕادیۆ: پەیوەندیی بەردەوام.","لە ناوچە مەترسیدارەکاندا تەنها لەسەر ڕێگا پاککراوەکان بڕۆ و لە ڕێگاکە لامەدە.","بە شەو: ڕووناکییەکانی ئۆتۆمبێل بەپێی ڕێنماییەکانی فەرماندەیی."]},{heading:"٢. ڕێکخستنی کاروان",body:"ڕێساکان:",points:["مەودا لە نێوان ئۆتۆمبێلەکاندا: ٥٠-١٠٠ مەتر، بەپێی فەرمانی سەرۆکی کاروان.","هەر ئۆتۆمبێلێک ڕادیۆیەک.","ئۆتۆمبێلی فریاکەوتن: لە کۆتاییدا.","ئۆتۆمبێلی چاککردنەوە: لە ناوەڕاستدا.","ئۆتۆمبێلی پێشڕەو: ٥٠٠ مەتر لە پێشەوە.","ئاگادارکردنەوە (Briefing) پێش دەستپێکردن."]},{heading:"٣. بۆسە",body:"ئەگەر کاروان کەوتە بۆسەوە:",points:["بە خێرایی لە ناوچەکە تێپەڕە — مەوەستە!","ڕاپۆرتی SALUTE بە خێرایی.","ئاراستەی هێرشەکە دیاری بکە.","MARCH بۆ برینداران، کاتێک شوێنەکە سەلامەت بوو.","داوای پشتیوانی (Backup) بکە.","ئاگاداری IED ی دووەم لەسەر ڕێگاکە بە."]},{heading:"٤. ڕووداوەکانی هاتوچۆ",body:"چی بکەین:",points:["لە شوێنێکی سەلامەت بوەستە.","سێگۆشەی ئاگادارکردنەوە دابنێ.","MARCH بۆ برینداران.","پەیوەندی بە ١١٥ و ١٢٢ەوە بکە.","ئاگر: هەموو کەسێک دوور بخەرەوە و لەو لایە بمێنەوە کە با لێیەوە دێت؛ ئەگەر ئۆتۆمبێلێک کە تەقەمەنیی تێدایە کەوتە ناو ئاگرەوە (ERG Guide 112، Division 1.1، 1.2، 1.3، 1.5): ١٦٠٠ مەتر (١ میل) لە هەموو لایەکەوە ناوچەکە دابخە و چۆڵی بکە، تەنانەت تیمەکانی فریاکەوتنیش؛ ئەگەر ئاگرەکە گەیشتە بارە تەقەمەنییەکە، مەیکوژێنەرەوە.","وێنە بگرە و ڕاپۆرت بنووسە."]}],media:[{kind:"video",src:"media/videos/mil_convoy.mp4",title:"کاروان",description:"ڕێکخستن"}],quiz:[{question:"بەپێی ئەم وانەیە، مەودای ئاسایی لە نێوان ئۆتۆمبێلەکانی کارواندا چەندە؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٥٠-١٠٠ مەتر",correct:!0},{text:"٢ مەتر",correct:!1},{text:"٥٠٠ مەتر",correct:!1}],explanation:"٥٠-١٠٠ مەتر، بەپێی بارودۆخ و فەرمانی سەرۆکی کاروان."},{question:"لە کاتی بۆسەدا، شۆفێر چی دەکات؟",options:[{text:"دەوەستێت",correct:!1},{text:"بە خێرایی لە ناوچەکە تێدەپەڕێت",correct:!0},{text:"لە ئۆتۆمبێلەکە دادەبەزێت",correct:!1},{text:"دەوەستێت بۆ ئەوەی وێنە بگرێت",correct:!1}],explanation:"بە خێرایی لە ناوچەی بۆسەکە تێپەڕە، ئەگەر ڕێگاکە کراوە بێت."},{question:"لە ناوچە مەترسیدارەکاندا، ئۆتۆمبێلە سەربازییەکان دەبێت بە کوێدا بڕۆن؟",options:[{text:"لە دەرەوەی ڕێگاکە، بۆ ئەوەی لە IED ی شاردراوە لە ناو قیرەکەدا دوور بن",correct:!1},{text:"لەسەر کورتترین ڕێگا، بۆ ئەوەی کاتێکی کەمتر لە مەترسیدا بمێننەوە",correct:!1},{text:"لەسەر لێواری ڕێگاکە، بۆ ئەوەی ئۆتۆمبێلەکانی تر تێپەڕن",correct:!1},{text:"تەنها لەسەر ڕێگا پاککراوەکان، بەبێ لادان لە ڕێگاکە",correct:!0}],explanation:"لە ناوچە مەترسیدارەکاندا تەنها لەسەر ڕێگا پاککراوەکان بڕۆ و لە ڕێگاکە لامەدە؛ بۆمبە دەستکردەکان (IED) لەسەر ڕێگاکان یەکێکن لە مەترسییە سەرەکییەکان."}]},{id:9,code:"MIL-109",icon:"Droplets",accent:"#0284c7",title:"پاککردنەوەی ئاو و پاکوخاوێنیی کەسی",subtitle:"Water Purification & Hygiene",summary:"پاککردنەوەی ئاو و پاکوخاوێنیی کەسی لە مەیداندا",blocks:[{body:"نەخۆشییەکانی ئاوی پیس دەتوانن لە دوژمن مەترسیدارتر بن! ئاوی پیس هێزەکان لاواز دەکات."},{heading:"١. پاککردنەوەی ئاو",body:"٤ ڕێگا:",points:["کوڵاندن: ١ خولەک بە کوڵانی تەواو — باوەڕپێکراوترین ڕێگایە بۆ کوشتنی میکرۆبەکان.","حەبی کلۆر/یۆد: بەپێی ڕێنماییەکانی سەر پاکەتەکە، و ٣٠ خولەک چاوەڕێ بکە.","فلتەری تایبەت (وەک LifeStraw).","SODIS: بوتڵی پلاستیکیی ڕوون، ٦ کاتژمێر لە بەر تیشکی خۆر (ئەگەر هەور هەبێت: ٢ ڕۆژ).","ئاوی وەستاو بەبێ پاککردنەوە مەخۆرەوە.","ڕیزبەندی: یەکەم بهێڵە لیتە و قوڕەکە بنیشێت، پاشان فلتەری بکە، پاشان پاکی بکەرەوە."]},{heading:"٢. پاکوخاوێنیی کەسی",body:"لە مەیداندا:",points:["شوشتنی دەست: پێش خواردن و دوای دەستاو.","لەشت بە بەردەوامی پاک بکەرەوە؛ ئەگەر ئاو کەم بێت، بە پارچە قوماشێکی تەڕ.","گۆرەوی ڕۆژانە بگۆڕە و جلەکانت پاک ڕابگرە.","پێیەکانت پاک و وشک ڕابگرە.","برینە بچووکەکان: بیشۆ و بە پێچانێکی پاک دایبپۆشە.","ددانەکانت ڕۆژانە ٢ جار بشۆ."]},{heading:"٣. خواردن",body:"سەلامەتیی خواردن:",points:["بەرواری بەسەرچوون بپشکنە.","خواردن بە تەواوی لێبنێ (ناوەڕاستەکەی بگاتە ٧٥°C).","خواردنی لێنراو زیاتر لە ٢ کاتژمێر لە پلەی گەرمیی ژووردا جێمەهێڵە (لە گەرمیی زیاتر لە ٣٢°C: ١ کاتژمێر).","خواردن لە مێش و تۆز دابپۆشە.","پاشماوەی خواردن دوور لە کەمپ بسووتێنە یان بیشارەوە.","ئاوی پاک زۆر بخۆرەوە."]},{heading:"٤. نەخۆشییە مەیدانییەکان",body:"باوترینەکان:",points:["سکچوون: شلەی ئاو، خوێ و شەکر (ORS) بخۆرەوە.","مەلاریا: تۆڕی مێشوولە و سپرێی دژە مێشوولە.","گەرمالێدان (Heat Stroke): سێبەر، ساردکردنەوەی خێرا و پەیوەندی بە ١٢٢ەوە بکە.","دابەزینی پلەی گەرمیی لەش (Hypothermia): بە هێواشی گەرمی بکەرەوە و جلە تەڕەکانی دابکەنە.","هەوکردن (ئینفێکشن): پێچانەکە ڕۆژانە بگۆڕە، یان کاتێک تەڕ یان پیس بوو.","ڕاپۆرتی هەر نەخۆشییەک بدە بە پزیشک."]}],media:[{kind:"video",src:"media/videos/mil_water.mp4",title:"ئاو",description:"پاککردنەوە"}],quiz:[{question:"باوەڕپێکراوترین ڕێگای پاککردنەوەی ئاو کامەیە؟",options:[{text:"حەب",correct:!1},{text:"کوڵاندن",correct:!0},{text:"فلتەر",correct:!1},{text:"تیشکی خۆر",correct:!1}],explanation:"کوڵاندن بۆ ماوەی ١ خولەک بە کوڵانی تەواو، باوەڕپێکراوترین ڕێگایە بۆ کوشتنی میکرۆبە نەخۆشخەرەکان."},{question:"خواردنی لێنراو تا چەند کاتژمێر دەتوانێت لە پلەی گەرمیی ژووردا بمێنێتەوە؟",options:[{text:"١٢ کاتژمێر",correct:!1},{text:"زیاتر نەبێت لە ٢ کاتژمێر (لە گەرمیی زیاتر لە ٣٢°C: ١ کاتژمێر)",correct:!0},{text:"٢٤ کاتژمێر",correct:!1},{text:"جیاوازی نییە",correct:!1}],explanation:"بەپێی ڕێنماییەکانی WHO، خواردنی لێنراو زیاتر لە ٢ کاتژمێر لە پلەی گەرمیی ژووردا جێمەهێڵە؛ لە گەرمیی زیاتر لە ٣٢°C، ١ کاتژمێر (USDA)."},{question:"ئاوی مەیدان بە چ ڕیزبەندییەک پاک دەکرێتەوە؟",options:[{text:"یەکەم بهێڵە لیتە و قوڕەکە بنیشێت، پاشان فلتەری بکە، پاشان پاکی بکەرەوە",correct:!0},{text:"یەکەم پاکی بکەرەوە، پاشان فلتەری بکە، پاشان بهێڵە لیتە و قوڕەکە بنیشێت",correct:!1},{text:"یەکەم فلتەری بکە، پاشان پاکی بکەرەوە، پاشان بهێڵە لیتە و قوڕەکە بنیشێت",correct:!1},{text:"یەکەم پاکی بکەرەوە، پاشان بهێڵە لیتە و قوڕەکە بنیشێت، پاشان فلتەری بکە",correct:!1}],explanation:"ڕیزبەندیی وانەکە ئەمەیە: یەکەم بهێڵە لیتە و قوڕەکە بنیشێت، پاشان فلتەری بکە، پاشان پاکی بکەرەوە."}]},{id:10,code:"MIL-110",icon:"Thermometer",accent:"#ea580c",title:"گەرما و سەرما — مەترسییەکانی کەشوهەوا",subtitle:"Heat & Cold Weather Operations",summary:"مەترسییەکانی گەرما و سەرما و خۆپاراستن",blocks:[{body:"لە هەرێمی کوردستان، پلەی گەرما لە هاویندا دەگاتە نزیکەی ٥٠°C، و لە زستاندا لە چیاکان لەوانەیە لە -١٥°C نزمتر ببێتەوە."},{heading:"١. مەترسییەکانی گەرما",body:"گەرمالێدان (Heat Stroke) دەکوژێت:",points:["ماندووبوون بە گەرما (Heat Exhaustion): سەرئێشە، دڵتێکهەڵاتن، ڕشانەوە، ئارەقکردنەوەی زۆر.","گەرمالێدان: پلەی گەرمیی لەش ٤٠°C یان زیاتر و تێکچوونی هۆش — باری نائاسایی! یەکسەر ساردی بکەرەوە و پەیوەندی بە ١٢٢ەوە بکە.","ئاو: نزیکەی ١ لیتر لە کاتژمێرێکدا لە کاری قورسدا؛ نەک زیاتر لە ١٫٤ لیتر لە کاتژمێرێکدا.","کاتەکانی کار و پشوو بەپێی پلەی گەرما (WBGT)؛ پشوودان لە سێبەردا.","ساردکردنەوەی گەرمالێدان: یەکسەر و پێش گواستنەوە؛ باشترین ڕێگا: هەموو لەش تا مل لە ناو ئاوی سارددا بۆ ماوەی ١٥ خولەک یان تا هۆشی دیسان ڕوون دەبێتەوە، کامیان زووتر بێت؛ ئەگەر نەکرا: دووشی سارد، خاولی یان چەرچەفی تەڕی سارد، کیسەی سەهۆڵ و باوەشێنکردن؛ تا هۆشی تێکچووە هیچ خواردنەوەیەکی مەدەرێ.","جلی ڕەنگ کاڵ و سووک."]},{heading:"٢. مەترسییەکانی سەرما",body:"دابەزینی پلەی گەرمیی لەش (Hypothermia) و سەرمابردن (Frostbite):",points:["دابەزینی پلەی گەرمیی لەش: پلەی گەرمیی لەش لە ٣٥°C نزمتر.","سەرمابردن: بەستنی پەنجەکان، گوێچکەکان و لووت.","جلی چین لەسەر چین.","بە هێواشی گەرمی بکەرەوە — نەک بە ئاگری ڕاستەوخۆ.","سەرمابردن: مەیسوو! لە ئاوی گەرمدا (٣٧-٣٩°C) دایبنێ، تەنها ئەگەر جارێکی تر نەبەستێتەوە.","ئەگەر لەرزین وەستا و هۆشی کەسەکە تێکچوو — باری نائاساییە! پەیوەندی بە ١٢٢ەوە بکە."]},{heading:"٣. جلی چین لەسەر چین",body:"سیستەمی سێ چین:",points:["١. چینی نزیک لە پێست (Base Layer): ئارەقە لە لەش دوور دەخاتەوە.","٢. چینی گەرمکەرەوە (Insulation): وەک فلیس.","٣. چینی دەرەوە (Shell): دژی با و باران.","دەستکێشی ئەستوور.","کڵاو و شاڵ: گەرمی لە هەر بەشێکی دانەپۆشراوی لەشەوە دەڕوات، نەک تەنها لە سەرەوە — هەموو لەشت دابپۆشە.","پۆتینی دژە ئاو."]}],media:[{kind:"video",src:"media/videos/mil_weather.mp4",title:"کەشوهەوا",description:"گەرما و سەرما"}],quiz:[{question:"لە کاری قورسدا لە گەرمادا، نزیکەی چەند ئاو لە کاتژمێرێکدا دەخورێتەوە؟",options:[{text:"تەنها کاتێک تینوو بیت",correct:!1},{text:"نزیکەی ١ لیتر (نەک زیاتر لە ١٫٤ لیتر)",correct:!0},{text:"٢ لیتر",correct:!1},{text:"٣ لیتر",correct:!1}],explanation:"بەپێی ڕێنماییەکانی سوپای ئەمریکا (TB MED 507): لە کاری قورسدا نزیکەی ١ لیتر لە کاتژمێرێکدا؛ زیاتر لە ١٫٤ لیتر لە کاتژمێرێکدا دەبێتە هۆی کەمبوونەوەی خوێی لەش."},{question:"لە سەرمابردندا (Frostbite)، کام کار هەڵەیە؟",options:[{text:"شوێنی سەرمابردووەکە بسوو یان بەفری لێ بدە",correct:!0},{text:"لە ئاوی گەرمدا (٣٧-٣٩°C) دایبنێ",correct:!1},{text:"جلە تەڕ و تەسکەکان دابکەنە",correct:!1},{text:"بریندار ببە بۆ شوێنێکی گەرم",correct:!1}],explanation:"سوون، بەفر و ئاگری ڕاستەوخۆ زیان بە پێست دەگەیەنن؛ بە ئاوی گەرم (٣٧-٣٩°C) گەرمی بکەرەوە."},{question:"بەپێی ئەم وانەیە، بریندارێکی گەرمالێدان چۆن سارد دەکرێتەوە؟",options:[{text:"تەنها دوای گواستنەوە بۆ نەخۆشخانە، بۆ ئەوەی ساردکردنەوە گەشتەکە دوا نەخات",correct:!1},{text:"یەکسەر و پێش گواستنەوە؛ باشترین ڕێگا: لەش تا مل لە ناو ئاوی سارددا",correct:!0},{text:"بە پێدانی ئاوی ساردی زۆر بۆ خواردنەوە کاتێک هۆشی هێشتا تێکچووە",correct:!1},{text:"بە هێواشی، بە پارچە قوماشێکی تەڕ لەسەر نێوچەوان، بۆ ئەوەی لەش تووشی شۆک نەبێت",correct:!1}],explanation:"گەرمالێدان یەکسەر و پێش گواستنەوە سارد بکەرەوە: باشترین ڕێگا هەموو لەش تا مل لە ناو ئاوی سارددا بۆ ماوەی ١٥ خولەک یان تا هۆشی دیسان ڕوون دەبێتەوە، کامیان زووتر بێت؛ تا هۆشی تێکچووە هیچ خواردنەوەیەکی مەدەرێ، و پەیوەندی بە ١٢٢ەوە بکە."}]},{id:11,code:"MIL-111",icon:"Ambulance",accent:"#dc2626",title:"گواستنەوەی برینداران (MEDEVAC)",subtitle:"Casualty Evacuation & 9-Line",summary:"گواستنەوەی سەلامەت و داواکاریی 9-Line MEDEVAC",blocks:[{body:"فریاکەوتنی سەرەتایی یەکەم هەنگاوە، بەڵام گواستنەوەی خێرا بۆ نەخۆشخانە ژیان ڕزگار دەکات."},{heading:"١. هەڵگرتنی برینداران",body:"تەکنیکەکان:",points:["بە ٢ کەس: یەکێک لە لای سەر و یەکێک لە لای قاچەکان.","هەڵگرتن لەسەر شان (Fireman Carry): بە یەک کەس — خێرا.","دارەبەست (برانکارد): بە ٤ کەس — باشترین.","دارەبەستی دەستکرد: ٢ دار و چاکەتێک یان بەتانییەک.","گومانی برینی مل یان پشت: مەیجووڵێنە، ئەگەر مەترسیی ئاگر یان تەقینەوە نەبێت.","سەر، مل و پشت پێکەوە و لەسەر یەک هێڵ بجووڵێنە."]},{heading:"٢. 9-Line MEDEVAC",body:"٩ خاڵ:",points:["Line 1: شوێنی هەڵگرتن (کۆئۆردینات / GPS).","Line 2: فریکوێنسیی ڕادیۆ و ناوی بانگکردن (Call Sign).","Line 3: ژمارەی برینداران بەپێی پێشینە (Urgent، Priority، Routine).","Line 4: کەرەستەی تایبەت (وەک Hoist).","Line 5: ژمارەی برینداران بەپێی جۆر: L لەسەر دارەبەست، A دەتوانن بە پێ بڕۆن.","Line 6: ئاسایشی شوێن: N دوژمن نییە، P لەوانەیە دوژمن هەبێت، E دوژمن هەیە، X پاراستنی چەکداری پێویستە.","Line 7: ڕێگای نیشانەکردنی شوێن (پانێڵ، دووکەڵی ڕەنگاوڕەنگ، ڕووناکی).","Line 8: نەتەوە و باری برینداران (سەرباز، مەدەنی، دیل).","Line 9: پیسبوونی CBRN لە کاتی شەڕدا؛ یان وەسفی زەویی شوێنەکە لە کاتی ئاشتیدا."]},{heading:"٣. شوێنی نیشتنەوەی هەلیکۆپتەر (LZ)",body:"بۆ هەلیکۆپتەر:",points:["قەبارە: بازنەیەک بە تیرەی لانیکەم ٣٥ مەتر بۆ هەلیکۆپتەری سووک (وەک UH-1)، ٥٠ مەتر بۆ UH-60، و ٨٠ مەتر بۆ هەلیکۆپتەرە بارهەڵگرەکان.","بێ تەل، درەخت و بەربەستی بەرز؛ زەوی ڕێک و پاک.","ئاراستەی با دیاری بکە (هەلیکۆپتەر ڕووەو با دەنیشێتەوە).","بە شەو: ٤ ڕووناکی بە شێوەی Y ی پێچەوانە.","تۆز و شتە سووکەکان لە شوێنەکە لابەرە، چونکە بای پەروانەکە دەیانفڕێنێت.","٣٠ مەتر دوور بمێنەوە تا ئاماژەت بۆ دەدرێت."]}],media:[{kind:"video",src:"media/videos/mil_medevac.mp4",title:"MEDEVAC",description:"گواستنەوە"},{kind:"image",src:"media/images/mil_9line.png",title:"9-Line",description:"فۆڕم"}],quiz:[{question:"کەمترین قەبارەی شوێنی نیشتنەوە (LZ) بۆ هەلیکۆپتەرێکی سووک (وەک UH-1) چەندە؟",options:[{text:"١٠ مەتر",correct:!1},{text:"٢٠ مەتر",correct:!1},{text:"٣٥ مەتر",correct:!0},{text:"٥ مەتر",correct:!1}],explanation:"بازنەیەک بە تیرەی ٣٥ مەتر بۆ هەلیکۆپتەری سووک؛ هەلیکۆپتەرە گەورەترەکان شوێنی گەورەتریان پێویستە (٥٠ مەتر بۆ UH-60)."},{question:"لە 9-Line دا، Line 1 چییە؟",options:[{text:"ژمارەی برینداران",correct:!1},{text:"شوێنی هەڵگرتن (کۆئۆردینات)",correct:!0},{text:"ئاسایشی شوێن",correct:!1},{text:"فریکوێنسیی ڕادیۆ",correct:!1}],explanation:"Line 1 شوێنی هەڵگرتنە بە کۆئۆردینات."},{question:"گومانی برینی مل یان پشت لە بریندارێک هەیە. کەی دەتوانیت بیجووڵێنیت؟",options:[{text:"هەر کاتێک دوو کەس هەبن بۆ هەڵگرتنی",correct:!1},{text:"کاتێک دەڵێت هەست بە دەست و قاچەکانی دەکات",correct:!1},{text:"تەنها ئەگەر مەترسیی ئاگر یان تەقینەوە هەبێت",correct:!0},{text:"هەر کاتێک شوێنی نیشتنەوەی هەلیکۆپتەر ئامادە بێت",correct:!1}],explanation:"لە گومانی برینی مل یان پشتدا، بریندارەکە مەجووڵێنە ئەگەر مەترسیی ئاگر یان تەقینەوە نەبێت؛ ئەگەر پێویست بوو، سەر، مل و پشت پێکەوە و لەسەر یەک هێڵ بجووڵێنە."}]},{id:12,code:"MIL-112",icon:"Search",accent:"#d97706",title:"گەڕان و ڕزگارکردن (SAR)",subtitle:"Search & Rescue Operations",summary:"ئۆپەراسیۆنەکانی گەڕان و ڕزگارکردنی کەسەکان",blocks:[{body:"لە کاتی بوومەلەرزە، لافاو و تەقینەوەکاندا، خەڵک لە ژێر داڕماوەکاندا دەمێننەوە. پێشمەرگە زۆر جار یەکەم کەسن کە دەگەنە شوێنەکە."},{heading:"١. ڕێگاکانی گەڕان",body:"شێوازەکان:",points:["هێڵی: ڕیز بە ڕیز، بە مەودایەکی ڕێک.","پێچاوپێچ (Spiral): لە ناوەڕاستەوە بەرەو دەرەوە.","بەشبەش (Sector): ناوچەکە دابەش دەکرێت بۆ چەند بەشێک.","سەگی گەڕان (K9).","لە کاتی ڕێکخراودا (بۆ نموونە هەر ١٠ خولەک جارێک) بێدەنگی ڕابگەیەنە و گوێ بگرە.","بە دەنگی بەرز بانگی کەسەکان بکە و گوێ لە وەڵام بگرە."]},{heading:"٢. لە ژێر داڕماوەکاندا",body:"ڕزگارکردن:",points:["شوێنی کەسەکە بدۆزەرەوە: بە گوێگرتن و سەگی گەڕان.","لەگەڵ قوربانییەکەدا قسە بکە و هێوری بکەرەوە.","بە هێواشی و وریاییەوە دەری بهێنە.","ئاگاداری مەترسیی داڕمانی دووەم بە.","MARCH یەکسەر بۆ برینداران.","پەیوەندی بە ١١٥ و ١٢٢ەوە بکە."]},{heading:"٣. ڕزگارکردن لە ئاو",body:"لافاو و خنکان:",points:["مەچۆ ناو ئاوەکە ئەگەر ڕاهێنانی ڕزگارکردنت نەبینیبێت.","لە کەنارەوە شتێکی درێژی پێ بگەیەنە یان بۆی فڕێ بدە: گوریس، لق، جلێکی درێژ.","چاکەتی ڕزگاربوون (Life Jacket) لەبەر بکە.","زنجیرەی مرۆیی تەنها لە ئاوی تەنک و هێمندا.","دوای ئەوەی کەسەکە لە ئاو هاتە دەرەوە، هەناسەی بپشکنە. ئەگەر بە ئاسایی هەناسەی نەدا: پەیوەندی بە ١٢٢ەوە بکە و ئەگەر ڕاهێنانت بینیوە، CPR لەگەڵ هەناسەدان دەست پێ بکە (لە خنکاندا یەکەمجار هەناسە دەوەستێت، بۆیە هەناسەدان لە هەموو شتێک گرنگترە)؛ ئەگەر ڕاهێنانت نەبینیوە یان ناتوانیت هەناسە بدەیت، تەنها پەستانی سنگ بدە. هەر کەسێک لە ئاو دەرهێنرابێت پێویستە پزیشک بیپشکنێت، تەنانەت ئەگەر باشیش دیار بێت.","١٥ سم ئاوی ڕەوان دەتوانێت مرۆڤ بخات؛ ٣٠ سم دەتوانێت ئۆتۆمبێل ببات."]}],media:[{kind:"video",src:"media/videos/mil_sar.mp4",title:"SAR",description:"گەڕان و ڕزگارکردن"}],quiz:[{question:"لە کاتی گەڕان لە ژێر داڕماوەکاندا، لە کاتی ڕێکخراودا (بۆ نموونە هەر ١٠ خولەک جارێک) چی دەکرێت؟",options:[{text:"هەمووان ڕادەکەن",correct:!1},{text:"بێدەنگی و گوێگرتن",correct:!0},{text:"جل دەگۆڕن",correct:!1},{text:"ئاو دەخۆنەوە",correct:!1}],explanation:"هەموو کارەکان دەوەستن و هەمووان بێدەنگ دەبن، بۆ ئەوەی دەنگی قوربانییەکان ببیسترێت."},{question:"ئەگەر کەسێک لە ئاودا خەریکی خنکان بێت و ڕاهێنانی ڕزگارکردنت نەبینیبێت، چی دەکەیت؟",options:[{text:"خۆم فڕێ دەدەمە ناو ئاوەکە",correct:!1},{text:"لە کەنارەوە شتێکی درێژی پێ دەگەیەنم یان بۆی فڕێ دەدەم",correct:!0},{text:"تەنها تەماشا دەکەم",correct:!1},{text:"ڕادەکەم و شوێنەکە جێدەهێڵم",correct:!1}],explanation:"لە کەنارەوە شتێکی درێژی پێ بگەیەنە یان بۆی فڕێ بدە و پەیوەندی بە ١١٥ەوە بکە؛ مەچۆ ناو ئاوەکە."},{question:"کەسێک کە لە ئاو دەرهێنراوە بە ئاسایی هەناسە نادات، و تۆ ڕاهێنانت بینیوە. چی دەکەیت؟",options:[{text:"تەنها پەستانی سنگ بدە، چونکە دوای خنکان هەناسەدان گرنگ نییە",correct:!1},{text:"کەسەکە سەرەوخوار بکە بۆ ئەوەی ئاو لە سییەکانی دەربچێت",correct:!1},{text:"چاوەڕێ بکە تا کەسەکە ئاوەکە بە کۆکە دەردەدات، پاشان کار بکە",correct:!1},{text:"پەیوەندی بە ١٢٢ەوە بکە و CPR لەگەڵ هەناسەدان دەست پێ بکە",correct:!0}],explanation:"ئەگەر بە ئاسایی هەناسەی نەدا، پەیوەندی بە ١٢٢ەوە بکە و ئەگەر ڕاهێنانت بینیوە CPR لەگەڵ هەناسەدان دەست پێ بکە: لە خنکاندا یەکەمجار هەناسە دەوەستێت، بۆیە هەناسەدان لە هەموو شتێک گرنگترە. هەر کەسێک لە ئاو دەرهێنرابێت پێویستە پزیشک بیپشکنێت."}]},{id:13,code:"MIL-113",icon:"Flame",accent:"#dc2626",title:"ئاگر لە بنکە سەربازییەکان و جبەخانەکاندا",subtitle:"Fire Safety in Military Bases",summary:"ڕێگریکردن لە ئاگر و چوونەدەرەوەی سەلامەت لە بنکە سەربازییەکان و جبەخانەکاندا",blocks:[{body:"ئاگر لە بنکە سەربازییەکاندا مەترسیدارترە، چونکە چەک، تەقەمەنی و سووتەمەنییان تێدایە. ئەگەر ئاگر گەیشتە تەقەمەنی یان لە نزیکییەوە بوو، هەوڵی کوژاندنەوەی مەدە: بچۆ دەرەوە، ناوچەکە دابخە و پەیوەندی بە ١١٥ەوە بکە."},{heading:"١. سەرچاوەکانی ئاگر",body:"لە بنکەکاندا:",points:["تەقەمەنی.","بەنزین و گازوایل.","سۆبەی چادرەکان.","مۆلیدە (جەنەراتۆر).","جگەرەکێشان.","وایەری کارەبای خراپ یان زیادبارکراو."]},{heading:"٢. ئاگرکوژێنەرەوەکان",body:"جۆرەکان (پۆلەکان بەپێی NFPA):",points:["تۆزی ABC: بۆ پۆلەکانی A، B و C — نەک بۆ D (کانزاکان) و نەک بۆ K (ڕۆنی چێشتخانە).","CO₂: بۆ ئاگری کارەبا و ئامێرەکان (C) و شلەمەنییەکان (B).","ئاگری تەقەمەنی بە ئاگرکوژێنەرەوە ناکوژێنرێتەوە: بچۆ دەرەوە، ناوچەکە دابخە، پەیوەندی بە ١١٥ەوە بکە.","P.A.S.S، تەنها کاتێک هەموو وەڵامەکانی پشکنینی پێش بەکارهێنان «بەڵێ» بن (ئاگرێکی بچووک و تازە؛ ئاگرکوژێنەرەوەی گونجاو؛ ڕێگای دەرچوون لە پشتتەوە؛ ئاگادارکردنەوە دراوە و پەیوەندی بە ١١٥ەوە کراوە؛ تۆ ڕاهێنراویت؛ هیچ دووکەڵ یان گەرمایەک ڕێگات ناگرێت): ڕابکێشە (Pull)، ئاراستەی بکە بەرەو بنی ئاگرەکە (Aim)، بگوشە (Squeeze)، بجووڵێنە (Sweep)؛ ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، بچۆ دەرەوە.","ئاگرکوژێنەرەوەکان لە نزیک دەرگاکانی چوونەدەرەوە دابنێ.","پشکنینی مانگانە بە چاو و چاکسازیی ساڵانە."]},{heading:"٣. جبەخانە (کۆگای تەقەمەنی)",body:"ڕێسا تایبەتەکان:",points:["قەدەغەیە: جگەرە، ئاگر، شقارتە، چەخماخە و مۆبایل.","لە گەرما و تیشکی خۆر بیپارێزە، بەپێی ڕێساکانی هەڵگرتنی تەقەمەنی.","جل و دەستکێشی دژە کارەبای ستاتیک (Anti-static).","ئامێرەکانی دۆزینەوەی ئاگر و سپرینکلەری خۆکار.","تەنها کەسانی ڕێپێدراو دەچنە ژوورەوە.","تۆماری تەواو: چی، چەند و لە کوێیە (بۆ ئاگادارکردنەوەی ١١٥)."]},{heading:"٤. پلانی چوونەدەرەوە",body:"ئەگەر ئاگر لە جبەخانە یان لە نزیک تەقەمەنی کەوتەوە: ئاگرەکە مەکوژێنەرەوە. بچۆ دەرەوە، ناوچەکە دابخە و پەیوەندی بە ١١٥ەوە بکە.",points:["سایرێن لێبدە و هەمووان ئاگادار بکەرەوە.","بە خێرایی بچۆ دەرەوە بە ڕێگایەکی دوور لە جبەخانەکە (لانیکەم ٢ ڕێگای چوونەدەرەوە).","ناوچەی چۆڵکردن و داخستن بۆ ئاگری جبەخانە: ئەو دوورییەی ڕێساکانی سەلامەتیی تەقەمەنیی فەرماندەییەکەت بۆ ئەو شوێنە دیاری دەکەن. دووریی ERG Guide 112، واتە ١٦٠٠ مەتر (١ میل) لە هەموو لایەکەوە، بۆ تەقەمەنیی کاتی گواستنەوەیە (بارهەڵگر یان ڤاگۆنی شەمەندەفەر لە ناو ئاگردا، یان گەیشتنی ئاگر بە بارە تەقەمەنییەکە)؛ وەک ڕێسا بۆ هەموو ئاگرێکی جبەخانە بەکاری مەهێنە.","خاڵی کۆبوونەوە: لە دەرەوەی ناوچەی چۆڵکردن، لە سەرەوەی با (ئەو لایەی با لێیەوە دێت)، لە پشت بەربەستێک، لە دەرەوەی هێڵی بینین و دوور لە پەنجەرەکان.","سەرژمێری: هەموو کەسێک بژمێردرێت؛ ناوی کەسە ونبووەکان بدە بە ١١٥.","پەیوەندی بە ١١٥ەوە بکە (شوێن، جۆر و بڕی تەقەمەنی)."]}],media:[{kind:"video",src:"media/videos/mil_fire_base.mp4",title:"ئاگر",description:"بنکەی سەربازی"}],quiz:[{question:"لە جبەخانەدا، چی قەدەغەیە؟",options:[{text:"تۆمارکردنی تەقەمەنی",correct:!1},{text:"جگەرە، ئاگر و مۆبایل",correct:!0},{text:"قسەکردن لەگەڵ هاوڕێیان",correct:!1},{text:"لەبەرکردنی جلی دژە کارەبای ستاتیک",correct:!1}],explanation:"جگەرە، ئاگر و مۆبایل قەدەغەن، چونکە دەتوانن ببنە هۆی ئاگر یان تەقینەوە."},{question:"بەپێی ERG Guide 112، ئەگەر بارهەڵگرێک کە تەقەمەنیی تێدایە کەوتە ناو ئاگرەوە، ناوچەی داخستن و چۆڵکردن دەبێت چەند بێت؟",options:[{text:"٥٠ مەتر",correct:!1},{text:"١٠٠ مەتر",correct:!1},{text:"١٦٠٠ مەتر (١ میل) لە هەموو لایەکەوە، تەنانەت تیمەکانی فریاکەوتنیش",correct:!0},{text:"٣٠٠ مەتر",correct:!1}],explanation:"ERG Guide 112 (تەقەمەنیی کاتی گواستنەوە، Division 1.1، 1.2، 1.3، 1.5): ئەگەر بارهەڵگر یان ڤاگۆنی شەمەندەفەر کەوتە ناو ئاگرەوە، ١٦٠٠ مەتر (١ میل) لە هەموو لایەکەوە ناوچەکە دابخە و چۆڵی بکە، تەنانەت تیمەکانی فریاکەوتنیش؛ ئەگەر ئاگرەکە گەیشتە بارە تەقەمەنییەکە، مەیکوژێنەرەوە و بهێڵە بسووتێت. بۆ ئاگری جبەخانە، ئەو دوورییە بەکاربهێنە کە لە ڕێساکانی سەلامەتیی تەقەمەنیی فەرماندەییەکەتدا هاتووە. خاڵی کۆبوونەوە لە دەرەوەی ناوچەی چۆڵکردن و لە سەرەوەی با بێت."},{question:"ئاگر لە جبەخانەدا دەکەوێتەوە. چی دەکەیت؟",options:[{text:"ئاگرەکە مەکوژێنەرەوە: بچۆ دەرەوە، ناوچەکە دابخە و پەیوەندی بە ١١٥ەوە بکە",correct:!0},{text:"ئاگرکوژێنەرەوەی CO₂ لەسەر سندووقە تەقەمەنییە سووتاوەکان بەکاربهێنە",correct:!1},{text:"سندووقەکان بە ئاو سارد بکەرەوە تا ئەوانی تر لە بنکەکە دەردەچن",correct:!1},{text:"تۆزی ABC بەکاربهێنە، چونکە بۆ پۆلەکانی A، B و C یە",correct:!1}],explanation:"ئەگەر ئاگر لە جبەخانە یان لە نزیک تەقەمەنی کەوتەوە، ئاگرەکە مەکوژێنەرەوە: بچۆ دەرەوە، ناوچەکە دابخە و پەیوەندی بە ١١٥ەوە بکە. ئاگری تەقەمەنی بە ئاگرکوژێنەرەوە ناکوژێنرێتەوە."}]},{id:14,code:"MIL-114",icon:"Handshake",accent:"#059669",title:"هاوکاری لەگەڵ بەرگریی شارستانی",subtitle:"Civil-Military Cooperation (CIMIC)",summary:"هاوکاریی نێوان پێشمەرگە و بەرگریی شارستانی (CIMIC)",blocks:[{body:"لە کارەساتەکاندا، پێشمەرگە و بەرگریی شارستانی پێکەوە کار دەکەن."},{heading:"١. ئەرکەکانی پێشمەرگە",body:"لە کارەساتەکاندا:",points:["گەڕان و ڕزگارکردن.","ئاسایش.","لۆجستیک.","فریاکەوتنی سەرەتایی.","پەیوەندی.","ئاوەدانکردنەوە."]},{heading:"٢. هەماهەنگی لەگەڵ بەرگریی شارستانی (١١٥)",body:"پەیوەندی:",points:["پەیوەندی بە ١١٥ەوە بکە.","کەناڵی پەیوەندیی هاوبەش.","سیستەمی فەرماندەیی ڕووداو (ICS).","ناوەندی ئۆپەراسیۆنەکانی باری نائاسایی (EOC).","ڕاپۆرتی METHANE.","لە ناو شاردا، فەرماندەیی هی دامەزراوە مەدەنییەکانە."]},{heading:"٣. هاوکاریی خەڵک",body:"هاوکاریی مرۆیی (Humanitarian Assistance):",points:["خواردن و ئاو.","چادر بۆ ئاوارەکان.","کلینیکی مەیدانی.","گواستنەوەی خەڵک و کەرەستە.","پاراستنی منداڵان.","ئاگادارکردنەوەی خەڵک."]},{heading:"٤. هۆشیاریی کۆمەڵایەتی",body:"فێرکردنی خەڵک:",points:["ڕاهێنانەکانی سەلامەتی.","هۆشیاریی مین.","قوتابخانەکان.","کەمپەین.","منداڵان: فێرکردنی سادە.","ڕادیۆ و تەلەفزیۆن."]}],media:[{kind:"video",src:"media/videos/mil_cimic.mp4",title:"CIMIC",description:"هاوکاری"}],quiz:[{question:"لە ناو شاردا لە کاتی کارەساتدا، فەرماندەیی هی کێیە؟",options:[{text:"هێزە سەربازییەکان",correct:!1},{text:"بەرگریی شارستانی",correct:!0},{text:"پۆلیس",correct:!1},{text:"جیاوازی نییە",correct:!1}],explanation:"دامەزراوە مەدەنییەکان (بەرگریی شارستانی) فەرماندەیی دەکەن و هێزە سەربازییەکان پشتیوانی دەکەن."},{question:"ئەرکی پێشمەرگە لە کاتی کارەساتدا چییە؟",options:[{text:"تەنها پاراستنی بنکەکانی خۆیان",correct:!1},{text:"دوورکەوتنەوە لە ناوچەی کارەساتەکە",correct:!1},{text:"وەرگرتنی فەرماندەیی هەموو دامەزراوە مەدەنییەکان",correct:!1},{text:"ڕزگارکردن، ئاسایش، لۆجستیک و فریاکەوتن، بە هەماهەنگی لەگەڵ ١١٥",correct:!0}],explanation:"پێشمەرگە بە هەماهەنگی لەگەڵ بەرگریی شارستانی (١١٥) پشتیوانی دەکەن: ڕزگارکردن، ئاسایش، لۆجستیک و فریاکەوتن."},{question:"پێشمەرگە لە کاتی کارەساتدا چۆن لەگەڵ بەرگریی شارستانی هەماهەنگی دەکەن؟",options:[{text:"ئۆپەراسیۆنێکی جیا دەکەن و تەنها لە کۆتاییدا ڕاپۆرت دەدەن",correct:!1},{text:"پەیوەندی بە ١١٥ەوە دەکەن، کەناڵی هاوبەش بەکاردەهێنن و لە ناو ICS دا کار دەکەن",correct:!0},{text:"بە درێژایی کارەکە تەنها کەناڵە ڕادیۆییە سەربازییەکانی خۆیان بەکاردەهێنن",correct:!1},{text:"چاوەڕێ دەکەن تا بەرگریی شارستانی داوایەکی نووسراو بۆ یارمەتی دەنێرێت",correct:!1}],explanation:"هەماهەنگی لەگەڵ بەرگریی شارستانی ئەمەیە: پەیوەندی بە ١١٥ەوە بکە، کەناڵی پەیوەندیی هاوبەش بەکاربهێنە و لە ناو سیستەمی فەرماندەیی ڕووداو (ICS) و EOC دا کار بکە؛ لە ناو شاردا، فەرماندەیی هی دامەزراوە مەدەنییەکانە."}]},{id:15,code:"MIL-115",icon:"Megaphone",accent:"#9333ea",title:"هۆشیارکردنەوە و ئاگادارکردنەوەی کۆمەڵایەتی",subtitle:"Community Safety Education",summary:"ڕۆڵی پێشمەرگە لە فێرکردنی خەڵک دەربارەی سەلامەتی و بەرگریی شارستانی",blocks:[{body:"ئەرکی پێشمەرگە تەنها شەڕ نییە. ئاگادارکردنەوەی خەڵک لە مەترسییەکان ژیان ڕزگار دەکات."},{heading:"١. هۆشیاریی مین",body:"فێرکردنی خەڵک:",points:["منداڵان: دەستی لێ مەدەن و بە گەورەکان بڵێن!","جووتیاران و بیناسازان: پێش هەڵکەندن لە لایەنی پەیوەندیدار بپرسن؛ نەبوونی نیشانەی ئاگادارکردنەوە بەو مانایە نییە کە شوێنەکە سەلامەتە.","شوانەکان: مەڕوماڵات لە ناوچەکانی مین مەلەوەڕێنن.","نیشانەکانی مین فێری خەڵک بکە، و ئەوەی کە هەرگیز نابێت لاببرێن.","ئەگەر مین یان شتێکی نەناسراوت بینی: لێی نزیک مەبەرەوە، خەڵک لێی دوور بخەرەوە و ڕایبگەیەنە؛ لە باری نائاساییدا پەیوەندی بە ١١٥ەوە بکە.","لە ناوچەیەک کە لەوانەیە مینی تێدا بێت: بوەستە، بێجووڵە بمێنەوە و پێیەکانت مەجووڵێنە، داوای یارمەتی بکە و چاوەڕێ بکە.","وانەکانی قوتابخانە."]},{heading:"٢. بوومەلەرزە",body:"فێرکردن:",points:["خۆت بدە بە زەویدا، خۆت داپۆشە، توند پێوەی بگرە (Drop, Cover, Hold On) — لە ژێر مێزێکی پتەودا، دوور لە پەنجەرەکان.","پشکنینی بیناکان.","جانتای باری نائاسایی: ئاو (٤ لیتر بۆ هەر کەسێک لە ڕۆژێکدا، بۆ لانیکەم ٣ ڕۆژ).","خاڵی کۆبوونەوە.","پلانی خێزان بۆ باری نائاسایی.","ڕاهێنانی بەردەوام لەسەر پلانەکە."]},{heading:"٣. ئاگر و ماڵ",body:"سەلامەتی:",points:["سۆبەی گاز: هەواگۆڕکێی باش (مەترسیی گازی CO).","کارەبا: پلاکەکان زیاد بار مەکە.","ئاگرکوژێنەرەوە لە هەموو ماڵێکدا.","ئاگادارکەرەوەی دووکەڵ (Smoke Alarm).","ژمارەی ١١٥ لە بیرت بێت.","٢ ڕێگای چوونەدەرەوە."]},{heading:"٤. فریاکەوتنی سەرەتایی",body:"بنەماکان:",points:["پەستانی سنگ (CPR): ٣٠:٢، ١٠٠-١٢٠ پەستان لە خولەکێکدا، قووڵایی ٥-٦ سم؛ ئەگەر ڕاهێنانت نەبینیوە، تەنها پەستانی سنگ (Hands-Only CPR).","خوێنبەربوون: پەستانی ڕاستەوخۆ و بەهێز.","شکان: مەیجووڵێنە و جێگیری بکە.","سووتان: ٢٠ خولەک ئاوی ڕەوانی فێنک.","ژەهراویبوون: پەیوەندی بە ١٢٢ەوە بکە و قوتووی مادەکە بپارێزە؛ هەوڵ مەدە بیڕشێنیتەوە و هیچ خواردن و خواردنەوەیەکی مەدەرێ.","١١٥ و ١٢٢ لەسەر دیوار بنووسە."]},{heading:"٥. ڕێکخستنی کەمپەینەکان",body:"چۆن:",points:["پلان: بابەت + ئامانج + ناوچە.","تیم: پێشمەرگە + بەرگریی شارستانی (١١٥) + تەندروستی.","شوێن: قوتابخانە، مزگەوت، گوند.","میدیا: پۆستەر، ڤیدیۆ، تۆڕە کۆمەڵایەتییەکان.","گرووپە ئامانجەکان: منداڵان، ئافرەتان، بەرپرسان.","هەڵسەنگاندن دوای کەمپەین."]}],media:[{kind:"video",src:"media/videos/mil_awareness.mp4",title:"هۆشیاری",description:"فێرکردن"},{kind:"image",src:"media/images/mil_campaign.png",title:"کەمپەین",description:"ڕێکخستن"}],quiz:[{question:"یەکەم وانە بۆ منداڵان دەربارەی مین چییە؟",options:[{text:"هەڵگرتن و لابردن",correct:!1},{text:"دەستی لێ مەدەن و بە گەورەکان بڵێن!",correct:!0},{text:"بەدوایدا بگەڕێن",correct:!1},{text:"بەردی تێ بگرن",correct:!1}],explanation:"دەستی لێ مەدەن، دوور بکەونەوە و بە گەورەکان بڵێن؛ گەورەکان پەیوەندی بە ١١٥ەوە دەکەن."},{question:"لە هەموو ماڵێکدا، چی لەسەر دیوار بنووسرێت؟",options:[{text:"ناوی خاوەنماڵ",correct:!1},{text:"١١٥ و ١٢٢",correct:!0},{text:"ڕەنگی دیوار",correct:!1},{text:"هیچ شتێک",correct:!1}],explanation:"ژمارەکانی باری نائاسایی: ١١٥ (بەرگریی شارستانی) و ١٢٢ (ئەمبولانس)."},{question:"کەمپەینی هۆشیاری لە کوێ دەگاتە زۆرترین خەڵک؟",options:[{text:"تەنها لە ناو سەربازگەدا",correct:!1},{text:"لە قوتابخانە، مزگەوت و گوندەکان",correct:!0},{text:"لە شوێنێکی دوور کە کەسی لێ نییە",correct:!1},{text:"بە نامەیەکی نهێنی بۆ یەک کەس",correct:!1}],explanation:"کەمپەین لەو شوێنانەی خەڵکی لێ کۆ دەبێتەوە (قوتابخانە، مزگەوت، گوند) دەگاتە زۆرترین کەس."}]},{id:16,code:"MIL-116",icon:"FireExtinguisher",accent:"#dc2626",title:"ئاگرکوژێنەرەوە — ڕاهێنانی تەواو",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینی هەموو جۆرەکانی ئاگرکوژێنەرەوە، پۆلەکانی ئاگر و ڕێکاری P.A.S.S بە وردی",blocks:[{body:"ئاگرکوژێنەرەوە (Fire Extinguisher) ئامێرێکی سەرەکییە بۆ کوژاندنەوەی ئاگرە بچووکەکان لە قۆناغی سەرەتاییدا. لە سەربازگە و بنکە سەربازییەکاندا، پێویستە هەموو پێشمەرگەیەک بتوانێت بە خێرایی و بە دروستی ئاگرکوژێنەرەوە بەکار بهێنێت. ئاگرکوژێنەرەوە بچووکەکان بە خێرایی بەتاڵ دەبن، زۆر جار لە چەند چرکەیەکدا، و کاتی دروستی بەتاڵبوون لەسەر لەیبڵەکە نووسراوە — بۆیە دەبێت بە خێرایی و بە دروستی بەکار بهێنرێن."},{heading:"١. پۆلەکانی ئاگر بەپێی NFPA (Fire Classes)",body:"بەپێی سیستەمی NFPA، ئاگر دابەش دەبێت بۆ ٥ پۆل. پۆلەکانی ئاگر لێرەدا بە پیتەکانی NFPA 10 نووسراون وەک سەرچاوەی پرۆژە؛ سیستەمی فەرمیی دهۆک هێشتا پشتڕاست نەکراوەتەوە. هاوتاکانی EN 2: NFPA A = EN A؛ NFPA B (شلە) = EN B؛ NFPA B (گاز) = EN C؛ NFPA C (ئامێری کارەبایی کە کارەبای تێدایە) هیچ پۆلێکی EN ی نییە؛ NFPA D = EN D؛ NFPA K = EN F. پۆلەکان:",points:["پۆلی A (ماددە ڕەقەکان): دار، کاغەز، قوماش، چادر. ئاگرکوژێنەرەوە: ئاو، تۆزی ABC، کەف.","پۆلی B (شلەمەنی و گازە ئاگرگرەکان): بەنزین، نەوت، دیزڵ، ڕۆن. شلەمەنی: CO₂، تۆزی ABC، کەف. گاز: یەکەمجار گازەکە ڕابگرە ئەگەر سەلامەت بوو؛ هەرگیز ئاگری گاز مەکوژێنەرەوە ئەگەر نەتوانیت گازەکە ڕابگریت. (هەرگیز ئاو بەکار مەهێنە!)","پۆلی C (کارەبا): مۆلیدە، پانێڵ، سویچ. ئاگرکوژێنەرەوە: CO₂، Clean Agent، تۆزی ABC. (ئاو و کەف بەکارمەهێنە مەگەر لەیبڵەکە پۆلی C یان نیشانەی تاقیکردنەوەی کارەبایی نیشان بدات، وەک هەندێک ئاگرکوژێنەرەوەی تەمی ئاو (water mist)!)","پۆلی D (کانزاکان): مەگنیسیۆم، ئەلەمنیۆم. ئاگرکوژێنەرەوە: تەنها ئاگرکوژێنەرەوەی Class D یان ماددەیەک کە ناوی ئەو کانزایە لەسەر لەیبڵەکەی هاتبێت، نەک ABC. (ئاو لەوانەیە ببێتە هۆی تەقینەوە!)","پۆلی K (چێشتخانە): ڕۆنەکانی چێشتخانە. ئاگرکوژێنەرەوە: Wet Chemical، نەک ABC. (ئاو ڕۆنی داغ بڵاو دەکاتەوە!)"]},{heading:"٢. جۆرەکانی ئاگرکوژێنەرەوە",body:"ڕەنگ پۆلی ئاگر نییە. بەپێی ستانداردی ئەوروپیی BS EN 3، لەشی ئاگرکوژێنەرەوەکە سوورە؛ لە بەریتانیا پارچەیەکی ڕەنگکراو (BS 7863) ماددەکە نیشان دەدات. وڵاتانی تر ڕەنگی تر بەکاردەهێنن و ڕەنگەکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە، بۆیە هەمیشە لەیبڵ و نیشانەکانی پۆل بخوێنەرەوە. پۆلەکانی خوارەوە بە پیتەکانی NFPA ن:",points:["ئاگرکوژێنەرەوەی ئاو (Water): هەمووی سوور، بێ پارچەی ڕەنگکراو — تەنها بۆ پۆلی A.","ئاگرکوژێنەرەوەی CO₂: پارچەی ڕەش — بۆ پۆلی B و ئامێرە کارەباییەکان کە کارەبایان تێدایە (B و C بەپێی NFPA؛ بەپێی EN 2، C گازە و CO₂ بۆ ئاگری گاز نییە). مەودای کورتە و بۆ ئاگری قووڵی دار و کاغەز نییە. تەنها دەسکەکە بگرە، هەرگیز دەست لە لوولەکە مەدە: زۆر سارد دەبێت و دەست دەبەستێنێت! لە ژوورێکی بچووکدا دوای بەکارهێنان بچۆ دەرەوە و هەوا بگۆڕە، چونکە CO₂ ئۆکسجین دەردەکات.","ئاگرکوژێنەرەوەی تۆزی ABC (Dry Powder): پارچەی شین — بۆ پۆلەکانی A، B، C؛ نەک بۆ D و K. باوترین جۆرە.","ئاگرکوژێنەرەوەی کەف (Foam): پارچەی کرێمی — بۆ پۆلی A و B. بۆ کارەبا بەکاری مەهێنە!","ئاگرکوژێنەرەوەی Clean Agent: پۆلەکانی بەپێی مۆدێل جیاوازن، بۆیە لەیبڵەکە بخوێنەرەوە (زۆرجار B و C بە پیتەکانی NFPA) — بۆ ئامێرە هەستیارەکان.","ئاگرکوژێنەرەوەی Wet Chemical: پارچەی زەرد — بۆ پۆلی K (NFPA K = EN F). ئاگرکوژێنەرەوەی Class D: دەبێت ناوی ئەو کانزایەی لەوێ بەکاردێت لەسەر لەیبڵەکەی هاتبێت."]},{heading:"٣. ڕێکاری P.A.S.S",body:"پێش بەکارهێنانی ئاگرکوژێنەرەوە (دەبێت هەموو وەڵامەکان «بەڵێ» بن): ئاگرەکە بچووک و تازە دەستی پێکردبێت، وەک ئاگرێک لە سەتڵی خاشاکدا؛ ئاگرکوژێنەرەوەکە گونجاو بێت؛ ڕێگای دەرچوون لە پشتتەوە بێت؛ ئاگادارکردنەوە درابێت و پەیوەندی بە ١١٥ەوە کرابێت؛ تۆ ڕاهێنراو بیت؛ هیچ دووکەڵ یان گەرمایەک ڕێگات نەگرێت. ئەگەر ئاگرەکە یەکسەر نەکوژایەوە، ئاگرکوژێنەرەوەکە بەتاڵ بوو یان دووکەڵ و گەرما زیادیان کرد، بوەستە، بچۆ دەرەوە و دەرگاکە دابخە. ژیان پێش موڵک دێت. P.A.S.S ڕێکاری گشتییە بۆ زۆربەی ئاگرکوژێنەرەوە دەستییەکان؛ ئاگرکوژێنەرەوەکانی Class D، Wet Chemical، Clean Agent و ئەوانەی لەسەر تایەن: بەپێی لەیبڵ و ڕێنماییەکانی کۆمپانیای دروستکەر بەکاریان بهێنە:",points:["P = Pull (ڕابکێشە): سنجاقی سەلامەتی ڕابکێشە.","A = Aim (ئاراستە بکە): لوولەکە ئاراستەی بنی ئاگرەکە بکە — نەک بەرەو گڕەکە!","S = Squeeze (بگوشە): دەسکەکانی ئاگرکوژێنەرەوەکە بە هێز بگوشە.","S = Sweep (بجووڵێنە): لوولەکە بەرەو چەپ و ڕاست بجووڵێنە تا ئاگرەکە دەکوژێتەوە."]},{heading:"٤. پشکنینی مانگانەی ئاگرکوژێنەرەوەکان",body:"هەموو مانگێک بە چاو بپشکنە (NFPA 10):",points:["پەستانی ناو ئاگرکوژێنەرەوەکە: ئەگەر پەستانپێوی هەبێت، دەرزییەکەی لە ناو ناوچەی سەوزدا بێت. ئاگرکوژێنەرەوەی CO₂ پەستانپێوی نییە: هەڵیبگرە بۆ ئەوەی هەست بکەیت پڕە.","سنجاقی سەلامەتی و مۆرەکەی: لە شوێنی خۆیاندا بن.","لوولە: نابێت شکاو یان گیراو بێت.","لەشی ئاگرکوژێنەرەوەکە: نابێت ژەنگاوی یان زیانپێگەیشتوو بێت.","ئەمانە لێک جیا بکەرەوە: پشکنین و چاکسازیی ساڵانە لەلایەن کەسێکی شارەزاوە؛ پڕکردنەوە (Recharge) دوای هەر بەکارهێنانێک، تەنانەت ئەگەر کورتیش بێت؛ هەر ٦ ساڵ جارێک، ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو (stored-pressure) کە پێویستیان بە تاقیکردنەوەی هایدرۆستاتیکی ١٢ ساڵە هەیە بەتاڵ دەکرێنەوە و ناوەوەیان دەپشکنرێت؛ تاقیکردنەوەی هایدرۆستاتیک (تاقیکردنەوەی پەستانی لەشەکەی) هەر ٥ ساڵ بۆ ئاگرکوژێنەرەوەکانی ئاو، کەف، CO₂ و تۆزی وشکی ستێنلێس ستیل (stainless steel)، و هەر ١٢ ساڵ بۆ ئاگرکوژێنەرەوەکانی تۆزی وشکی پەستانی هەڵگیراو کە لەشیان لە پۆڵای ئاسایی (mild steel)، بڕنجی لەحیمکراو (brazed brass) یان ئەلەمنیۆمە. تاقیکردنەوە گۆڕین نییە. ڕێساکانی دهۆک هێشتا پشتڕاست نەکراونەتەوە."]},{heading:"٥. مەترسییە تایبەتەکان لە بنکە سەربازییەکاندا",body:"بنکە سەربازییەکان شوێنی هەستیارن:",points:["سووتەمەنی و بەنزین: کۆگای سووتەمەنی — پۆلی B.","جبەخانە و تەقەمەنی: مەترسیی تەقینەوە — ئاگرەکە مەکوژێنەرەوە! تا ئەو دوورییە دوور بکەوەرەوە کە ڕێساکانی سەلامەتیی تەقەمەنیی فەرماندەییەکەت بۆ ئەو شوێنە دیاری دەکەن، ناوچەکە دابخە و پەیوەندی بە ١١٥ەوە بکە. دووریی ERG Guide 112، واتە ١٦٠٠ مەتر (١ میل) لە هەموو لایەکەوە، بۆ تەقەمەنیی کاتی گواستنەوەیە (ئۆتۆمبێلێک کە تەقەمەنیی تێدایە لە ناو ئاگردا، یان گەیشتنی ئاگر بە بارە تەقەمەنییەکە).","مۆلیدە و کارەبا: پۆلی C — CO₂، Clean Agent یان تۆزی ABC؛ ئەگەر توانیت، یەکەم جار کارەبا بپچڕێنە.","چادر و کۆنتەینەر: ماددە وشکەکان — پۆلی A.","ئاگرکوژێنەرەوەکان لە نزیک دەرگاکان دابنێ؛ دووریی گەیشتن بە ئاگرکوژێنەرەوەیەک لە ٢٣ مەتر زیاتر نەبێت بۆ پۆلی A، و ٩-١٥ مەتر بۆ پۆلی B (NFPA 10)."]}],media:[{kind:"video",src:"media/videos/mil_fire_ext.mp4",title:"ئاگرکوژێنەرەوە",description:"ڕێکاری P.A.S.S بۆ پێشمەرگە"}],quiz:[{question:"بە پیتەکانی NFPA، ئاگرکوژێنەرەوەی CO₂ بۆ کام پۆلەکانی ئاگر گونجاوە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییە ئاگرگرەکان (B) و ئامێرە کارەباییەکان (C) گونجاوە. بەپێی EN 2، C ئاگری گازە و CO₂ بۆ ئەوان نییە."},{question:"لە ڕێکاری P.A.S.S دا، لوولەی ئاگرکوژێنەرەوەکە دەبێت ئاراستەی کوێ بکرێت؟",options:[{text:"سەری گڕەکە",correct:!1},{text:"بنی ئاگرەکە",correct:!0},{text:"دوور لە ئاگرەکە",correct:!1},{text:"بنمیچی ژوورەکە",correct:!1}],explanation:"هەمیشە لوولەکە ئاراستەی بنی ئاگرەکە بکە."},{question:"بۆچی ئاو بەسەر ئاگری ڕۆندا (پۆلی K) ناڕژێنرێت؟",options:[{text:"هیچ کارێک ناکات",correct:!1},{text:"ئاو ڕۆنی داغ بڵاو دەکاتەوە و دەبێتە هۆی تەقینەوە",correct:!0},{text:"ڕۆن ئاوەکە هەڵدەمژێت",correct:!1},{text:"ئاو خۆی دەسووتێت",correct:!1}],explanation:"ئاو لەسەر ڕۆنی داغ بە خێرایی دەبێتە هەڵم و ڕۆنی گڕگرتوو بڵاو دەکاتەوە (Flash Fire)."}]},{id:17,code:"MIL-117",icon:"Heart",accent:"#db2777",title:"فریاکەوتنی سەرەتایی و CPR",subtitle:"First Aid & CPR — Complete Training",summary:"ڕاهێنانی تەواو لەسەر فریاکەوتنی سەرەتایی، پەستانی سنگ (CPR) و مامەڵەکردن لەگەڵ باری نائاسایی لە بنکە سەربازییەکاندا",blocks:[{body:"فریاکەوتنی سەرەتایی (First Aid) ئەو هاوکارییە سەرەتاییەیە کە پێش گەیشتنی تیمە پزیشکییەکان پێشکەشی کەسی بریندار یان نەخۆش دەکرێت. لە بنکە سەربازییەکاندا، مەترسیی برینداربوون زۆر بەرزە — لە برینەکانی شەڕ و تەقینەوەکانەوە تا شۆکی کارەبا و کەوتنەخوارەوە. پێویستە هەموو پێشمەرگەیەک بزانێت چۆن CPR بکات، خوێنبەربوون ڕابگرێت، و بریندار بپارێزێت تا گەیشتنی ئەمبولانس (١٢٢)."},{heading:"١. CPR — زیندووکردنەوەی دڵ و سی (بە وردی)",body:"CPR ڕێکارێکی ڕزگارکردنی ژیانە کاتێک دڵی مرۆڤ یان هەناسەدانی دەوەستێت:",points:["١. سەلامەتیی شوێن: دڵنیا ببەوە کە شوێنی بریندارەکە سەلامەتە (تەقەمەنی، ئاگر، گاز نییە؟).","٢. وەڵامدانەوە: لەسەر شانەکانی بدە و بە دەنگی بەرز بپرسە: «باشیت؟ دەنگم دەبیستیت؟»","٣. پەیوەندی بە ١٢٢ەوە: ئەگەر وەڵامی نەدایەوە و بە ئاسایی هەناسەی نەدا (لە ماوەی کەمتر لە ١٠ چرکەدا بپشکنە)، یەکسەر پەیوەندی بە ١٢٢ەوە بکە و AED بهێنە.","٤. پەستانەکانی سنگ (Compressions): ٣٠ پەستان لە ناوەڕاستی سنگ — قووڵایی: ٥-٦ سم، خێرایی: ١٠٠-١٢٠ پەستان لە خولەکێکدا.","٥. هەناسەپێدان: سەری بەرەو دواوە ببە و چەناگەی بەرز بکەرەوە، لووتی بگرە، ٢ هەناسەی ١ چرکەیی بدە. ئەگەر ڕاهێنانت نەبینیوە یان نەتەوێت هەناسە بدەیت، تەنها پەستانی سنگ بدە (Hands-Only CPR)، بەبێ وەستان.","٦. بەردەوامی (٣٠ بە ٢): تا ئەمبولانس (١٢٢) دەگات یان بریندارەکە بە ئاسایی هەناسە دەدات.","٧. AED: هەر کە گەیشت، بیکەرەوە، پادەکان بلکێنە سەر سنگ و پەیڕەوی دەنگی ئامێرەکە بکە."]},{heading:"٢. کۆنترۆڵکردنی خوێنبەربوون",body:"خوێنبەربوونی توند دەتوانێت لە ماوەیەکی کەمدا مرۆڤ بکوژێت:",points:["پەستانی ڕاستەوخۆ: پارچە قوماشێکی پاک بخە سەر برینەکە و بە هێز پەستان بدە. ئەگەر قوماشەکە بە خوێن تێر بوو، لای مەبە — پارچەیەکی تر بخە سەری.","پڕکردنەوەی برین (Wound Packing): بۆ برینە قووڵەکانی مل، ژێر باڵ یان نێوان ڕان، برینەکە بە پەڕۆی برینپێچ پڕ بکەرەوە و پەستان بدە.","تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونی مەترسیدار لە دەست یان قاچ زوو بەکاری بهێنە — ٥-٧ سم سەرووتر لە برینەکە؛ کاتەکە بنووسە و هەرگیز شلی مەکەرەوە.","شتی چەقیو: ئەگەر ئاسن، شووشە یان پارچەی تەقینەوە لە ناو برینەکەدا بن — دەری مەهێنە! دەوروبەری جێگیر بکە."]},{heading:"٣. چارەسەرکردنی سووتان",body:"سووتان لە مەیدان و بنکەکاندا:",points:["سووتانی گەرمی: ٢٠ خولەک ئاوی ڕەوانی فێنک بڕژێنە سەر شوێنی سووتاوەکە (نەک سەهۆڵ).","سووتانی کیمیایی: یەکەم تۆزی وشک بە نەرمی لابەرە، پاشان بە ئاوێکی زۆر ٢٠ خولەک بیشۆ.","سووتانی کارەبا: یەکەم کارەبا بپچڕێنە! پاشان وەک سووتانی گەرمی، و پەیوەندی بە ١٢٢ەوە بکە.","بڵقەکانی سووتان مەتەقێنە؛ ڕۆن، کرێم و هەویری ددان بەکار مەهێنە."]},{heading:"٤. شکان و برینەکانی پشت",body:"لە کاتی کەوتنەخوارەوەدا:",points:["جێگیرکردن (Splinting): ئەندامی بریندار مەجووڵێنە — بە دارێک جێگیری بکە.","پاراستنی پشت: ئەگەر کەسێک لە بەرزییەوە کەوتە خوارەوە، مەیجووڵێنە؛ بە جێگیری ڕایبگرە و پەیوەندی بە ١٢٢ەوە بکە. تەنها ئەگەر شوێنەکە مەترسیدار بێت (ئاگر، هاتوچۆ، ڕووخان، گاز، بەرزبوونەوەی ئاو) بیجووڵێنە، و سەر، مل و پشتی لەسەر یەک هێڵ ڕابگرە. ئەگەر پێویستی بە CPR هەبێت، لەسەر پشت لەسەر ڕووێکی ڕەق پاڵی بخە. لەسەر لا (Recovery Position) دایمەنێ.","ساردکردنەوە: سەهۆڵ لە ناو پارچە قوماشێکدا بپێچە و بیخە سەر شوێنی ئازارەکە (نەک ڕاستەوخۆ لەسەر پێست)."]},{heading:"٥. شۆکی کارەبا و ڕزگارکردن",body:"کارەبا دەتوانێت دڵ ڕابگرێت:",points:["یەکسەر کارەبا بپچڕێنە! تا کارەبا نەپچڕێنرابێت، دەست لە بریندارەکە مەدە.","ئەگەر نەتتوانی بیپچڕێنیت و کارەباکە فشارنزم بێت: بە دارێکی وشک یان پلاستیک وایەرەکە لە بریندارەکە جیا بکەرەوە. لە کارەبای فشاربەرز نزیک مەبەوە و پەیوەندی بە ١١٥ەوە بکە.","هەموو ئەو کەسانەی کارەبا لێیانی داوە دەبێت بچنە نەخۆشخانە (١٢٢)."]}],media:[{kind:"video",src:"media/videos/mil_cpr.mp4",title:"CPR و فریاکەوتنی سەرەتایی",description:"ڕاهێنانی CPR بۆ پێشمەرگە"}],quiz:[{question:"لە ڕێکاری CPR دا، چەند پەستانی سنگ لە خولەکێکدا دەبێت بدرێت؟",options:[{text:"٥٠-٧٠",correct:!1},{text:"٨٠-٩٠",correct:!1},{text:"١٠٠-١٢٠",correct:!0},{text:"١٥٠+",correct:!1}],explanation:"١٠٠-١٢٠ پەستان لە خولەکێکدا."},{question:"ئەگەر شتێکی تیژ لە ناو برینەکەدا چەقیبوو، چی دەکەیت؟",options:[{text:"دەری دەهێنم",correct:!1},{text:"لە شوێنی خۆی دەیهێڵمەوە و پەیوەندی بە ١٢٢ەوە دەکەم",correct:!0},{text:"دەستی لێ نادەم و بریندارەکە جێدەهێڵم و دەڕۆم",correct:!1},{text:"بە ئاو دەیشۆم و دەری دەهێنم",correct:!1}],explanation:"دەرهێنانی شتەکە خوێنبەربوون زیاتر دەکات؛ دەوروبەری جێگیر بکە و پەیوەندی بە ١٢٢ەوە بکە."},{question:"ئەگەر کارەبا لە کەسێک درابێت، یەکەم کار چییە؟",options:[{text:"دەستی دەگرم",correct:!1},{text:"CPR دەکەم",correct:!1},{text:"کارەباکە دەپچڕێنم",correct:!0},{text:"ئاوی بەسەردا دەکەم",correct:!1}],explanation:"پێویستە یەکەم جار کارەبا بپچڕێنرێت."}]}],t={lessons:e};export{t as default,e as lessons};
